`test/force.test.mjs`:

```javascript
// Run: PKG=<package dir> node --import ./test/nonet.mjs --test test/
// F1 to F4 fail on zimakri 0.1.0 and pass with the patch.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, writeFileSync, appendFileSync, existsSync, statSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';

const PKG = resolve(process.env.PKG ?? './pkg');
const { init, check } = await import(pathToFileURL(join(PKG, 'src/init.js')).href);
const fresh = () => mkdtempSync(join(tmpdir(), 'zim-'));
const sha = (s) => createHash('sha256').update(s, 'utf8').digest('hex');
const LINE = '{"at":"2026-10-24T06:00:00Z","kind":"received","usdc":"0.05","job":"j1"}\n';

test('F1 init --force keeps the earnings ledger', () => {
  const dir = fresh(); init({ dir, name: 'Ledger Keeper' });
  appendFileSync(join(dir, 'memory/earnings/ledger.jsonl'), LINE);
  init({ dir, name: 'Ledger Keeper', force: true });
  assert.equal(readFileSync(join(dir, 'memory/earnings/ledger.jsonl'), 'utf8'), LINE);
});

test('F2 init --force keeps memory/index.json entries', () => {
  const dir = fresh(); init({ dir, name: 'Index Keeper' });
  const p = join(dir, 'memory/index.json');
  const idx = JSON.parse(readFileSync(p, 'utf8')); idx.entries.push({ file: 'episodic/2026-10-24.md' });
  writeFileSync(p, JSON.stringify(idx));
  init({ dir, name: 'Index Keeper', force: true });
  assert.equal(JSON.parse(readFileSync(p, 'utf8')).entries.length, 1);
});

test('F3 init --force keeps an edited SOUL.md and check stays ok', () => {
  const dir = fresh(); init({ dir, name: 'Soul Keeper' });
  const p = join(dir, 'SOUL.md');
  const edited = readFileSync(p, 'utf8') + '\n## My own words\n\nI write tests first.\n';
  writeFileSync(p, edited);
  const r = init({ dir, name: 'Soul Keeper', force: true });
  assert.equal(readFileSync(p, 'utf8'), edited);
  assert.equal(r.config.soul_sha256, sha(edited));
  assert.deepEqual(check(dir).filter((x) => !x.startsWith('note:')), []);
});

test('F4 the result lists what was kept', () => {
  const dir = fresh(); init({ dir, name: 'List Keeper' });
  const r = init({ dir, name: 'List Keeper', force: true });
  assert.ok(Array.isArray(r.kept) && r.kept.includes('memory/earnings/ledger.jsonl') && r.kept.includes('SOUL.md'));
});

test('K1 --force keeps the DID and the key', () => {
  const dir = fresh(); const a = init({ dir, name: 'Key Keeper' });
  const key = readFileSync(join(dir, '.zimakri/identity/agent.key'));
  const b = init({ dir, name: 'Key Keeper', force: true });
  assert.equal(b.did, a.did);
  assert.deepEqual(readFileSync(join(dir, '.zimakri/identity/agent.key')), key);
  assert.equal(statSync(join(dir, '.zimakri/identity/agent.key')).mode & 0o777, 0o600);
});

test('K2 a SOUL.md for another DID is replaced, not trusted', () => {
  const dir = fresh();
  writeFileSync(join(dir, 'SOUL.md'), '# SOUL of someone else\n\nDID: did:key:zOther\n');
  const r = init({ dir, name: 'Clean Start' });
  assert.match(readFileSync(join(dir, 'SOUL.md'), 'utf8'), new RegExp(`DID: ${r.did}`));
  assert.deepEqual(check(dir).filter((x) => !x.startsWith('note:')), []);
});

test('K3 a clean init passes check and the LAX offer rules, offline', () => {
  const dir = fresh(); const r = init({ dir, name: 'Clean Agent', endpoint: 'https://agent.example.org/lax' });
  assert.deepEqual(check(dir), []);
  assert.deepEqual(r.offer.constitutional_constraints.length, 5);
  assert.ok(existsSync(join(dir, 'WAKE.md')) && existsSync(join(dir, 'wake.json')));
});

test('K4 the CLI: init without --force refuses, --json lists kept files, key never printed', () => {
  const dir = fresh(); const bin = join(PKG, 'bin/zimakri.js');
  execFileSync(process.execPath, [bin, 'init', '--dir', dir, '--name', 'Cli Agent']);
  let code = 0; try { execFileSync(process.execPath, [bin, 'init', '--dir', dir], { stdio: 'pipe' }); } catch (e) { code = e.status; }
  assert.equal(code, 1);
  const out = execFileSync(process.execPath, [bin, 'init', '--dir', dir, '--force', '--json'], { encoding: 'utf8' });
  assert.ok(!out.includes('PRIVATE KEY'));
  assert.ok(JSON.parse(out).kept.includes('SOUL.md'));
});
```


