#!/usr/bin/env node
// research-brief "<what you want to know>" [--out <dir>] [--sovereign] [--audience "<who>"]
import { runTemplate } from './index.js';
const argv = process.argv.slice(2);
const opt = (name) => { const i = argv.indexOf(name); return i >= 0 ? argv[i + 1] : undefined; };
const skip = new Set();
for (const n of ['--out', '--audience']) { const i = argv.indexOf(n); if (i >= 0) { skip.add(i); skip.add(i + 1); } }
const brief = argv.filter((a, i) => !skip.has(i) && !a.startsWith('--')).join(' ');
const input = { brief, sovereign: argv.includes('--sovereign') };
if (opt('--audience')) input.audience = opt('--audience');
try {
  const r = await runTemplate(input, { outDir: opt('--out') ?? './brief-out' });
  console.log(JSON.stringify(r, null, 2));
} catch (e) {
  console.error(`research-brief: ${e.message}`);
  process.exit(1);
}
