const argOf = (args, flag) => args[args.indexOf(flag) + 1];

// a fake engine: writes what a real goal run writes, prints the real footer
function fakeEngine({ code = 0, files = { 'brief.md': '## Summary\nWater boils at 100 C at sea level.\n' }, cost = '0.0421', stderr = '' } = {}) {
  const calls = [];
  const exec = async (args) => {
    calls.push(args);
    const dir = argOf(args, '--out-dir');
    for (const [name, text] of Object.entries(files)) {
      await mkdir(dirname(join(dir, name)), { recursive: true });
      await writeFile(join(dir, name), text);
    }
    const stdout = `\u001b[90m   Total: 41.2s · 7 model calls · $${cost}\u001b[0m\n`;
    return { code, stdout, stderr };
  };
  return { exec, calls };
}

