`test/debate.test.ts`:

```ts
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { debate, NO_CASE, type DebateInput, type RouteArgs, type RouteResult } from '../src/debate.ts';

const input: DebateInput = {
  facts_text: [
    'Top 10 holders own 41.7 percent of the supply.',
    'Liquidity pool holds 182,400 USD, locked for 90 days.',
    'Mint authority is revoked.',
    'Token age is 12 days.',
  ].join('\n'),
  level: 'medium',
  points: 46,
  flag_ids: ['top10_concentration', 'young_token'],
  unknown: ['team wallets'],
};

const SOUND = 'Mint authority is revoked and the pool of 182,400 USD is locked for 90 days, so supply and liquidity cannot be changed at will.';
const FRAGILE = 'Top 10 holders own 41.7 percent of the supply and the token is 12 days old, so a few wallets weigh heavily on a short history.';
const REVIEW = { text: 'Concentration of 41.7 percent at 12 days is the main weight; the lock of 90 days limits liquidity risk.', weight: ['top10_concentration', 'young_token', 'made_up'], unknown: ['team wallets'], tension: 'Whether the lock offsets the concentration.' };

type Script = Partial<Record<'sound' | 'fragile' | 'reviewer', string | ((a: RouteArgs) => Promise<RouteResult>)>>;

function fakeRoute(script: Script = {}) {
  const calls: { args: RouteArgs; at: number; done?: number }[] = [];
  const defaults = { sound: SOUND, fragile: FRAGILE, reviewer: JSON.stringify(REVIEW) };
  const route = async (args: RouteArgs): Promise<RouteResult> => {
    const entry = { args, at: calls.length };
    calls.push(entry);
    const role = args.payload.role;
    const s = script[role] ?? defaults[role];
    if (typeof s === 'function') return s(args);
    await new Promise((r) => setTimeout(r, 5));
    return { content: s, model: `model-${role}`, cost_usd: role === 'reviewer' ? 0.02 : 0.005 };
  };
  return { route, calls };
}

test('A1 advocates run in parallel with roles sound and fragile, then the reviewer with both texts and the facts', async () => {
  let inFlight = 0;
  let maxInFlight = 0;
  const seen: RouteArgs[] = [];
  const route = async (args: RouteArgs): Promise<RouteResult> => {
    seen.push(args);
    inFlight++;
    maxInFlight = Math.max(maxInFlight, inFlight);
    await new Promise((r) => setTimeout(r, 20));
    inFlight--;
    const role = args.payload.role;
    return { content: role === 'sound' ? SOUND : role === 'fragile' ? FRAGILE : JSON.stringify(REVIEW) };
  };
  const d = await debate(input, { route, mode: 'on' });
  assert.equal(d.status, 'ok');
  assert.deepEqual(seen.map((a) => a.payload.role), ['sound', 'fragile', 'reviewer']);
  assert.equal(maxInFlight, 2);
  for (const a of seen) {
    assert.equal(a.task_type, 'risk_debate');
    assert.equal(a.tier_class, 'text');
    assert.equal(a.constitutional_flag, false);
    assert.equal(a.agent_id, 'golden-kog');
    assert.ok(a.context_tokens > 0);
    assert.ok(a.payload.prompt.includes(input.facts_text));
  }
  assert.equal(seen[0].complexity, 'exec');
  assert.equal(seen[1].complexity, 'exec');
  assert.equal(seen[2].complexity, 'apex');
  assert.ok(seen[2].payload.prompt.includes(SOUND));
  assert.ok(seen[2].payload.prompt.includes(FRAGILE));
  assert.equal(d.sound, SOUND);
  assert.equal(d.fragile, FRAGILE);
  assert.equal(d.reviewer, REVIEW.text);
});

test('A2 a number not in facts_text replaces the advocate part, and drops the debate for the reviewer', async () => {
  const a = fakeRoute({ fragile: 'Top 10 holders own 55 percent of the supply.' });
  const d = await debate(input, { route: a.route });
  assert.equal(d.status, 'ok');
  assert.equal(d.fragile, NO_CASE);
  assert.equal(d.sound, SOUND);
  assert.ok(d.rejected.some((r) => r.startsWith('fragile:') && r.includes('55')));
  // written differently from the facts (182400 vs 182,400) is refused too
  const b = fakeRoute({ sound: 'The pool holds 182400 USD.' });
  const d2 = await debate(input, { route: b.route });
  assert.equal(d2.sound, NO_CASE);

  const c = fakeRoute({ reviewer: JSON.stringify({ ...REVIEW, text: 'Concentration near 60 percent.' }) });
  const d3 = await debate(input, { route: c.route });
  assert.equal(d3.status, 'rejected');
  assert.equal(d3.sound, '');
  assert.equal(d3.fragile, '');
  assert.equal(d3.reviewer, '');
  assert.deepEqual(d3.weight, []);
  assert.ok(d3.rejected.some((r) => r.startsWith('reviewer:') && r.includes('60')));
});

test('A3 refused words, long dashes, non Latin digits, too many words and check problems are refused', async () => {
  const cases: [string, string][] = [
    ['The structure looks bullish.', 'refused word: bullish'],
    ['A clear Entry here.', 'refused word: entry'],
    ['Wait for a price   target.', 'refused word: price target'],
    ['Mint authority is revoked — good.', 'dash character'],
    ['Mint authority is revoked - good.', 'dash character'],
    ['Token age is ١٢ days.', 'non Latin digit'],
    [Array(181).fill('word').join(' '), '181 words, over 180'],
    ['Mint authority is revoked.', 'check: guard said no'],
  ];
  for (const [text, reason] of cases) {
    const check = (t: string) => (reason.startsWith('check') && t === text ? ['guard said no'] : []);
    const { route } = fakeRoute({ sound: text });
    const d = await debate(input, { route, check });
    assert.equal(d.sound, NO_CASE, text);
    assert.ok(d.rejected.includes(`sound: ${reason}`), `${text} -> ${d.rejected.join(' | ')}`);
  }
  // words inside other words are fine: "bearing", "reentry"
  const { route } = fakeRoute({ sound: 'Mint authority is revoked, bearing no reentry of supply.' });
  assert.equal((await debate(input, { route })).sound, 'Mint authority is revoked, bearing no reentry of supply.');
  // the reviewer has its own limit of 150 words
  const long = fakeRoute({ reviewer: JSON.stringify({ ...REVIEW, text: Array(151).fill('word').join(' ') }) });
  const d = await debate(input, { route: long.route });
  assert.equal(d.status, 'rejected');
  assert.ok(d.rejected.includes('reviewer: 151 words, over 150'));
});

test('A4 reviewer JSON is parsed, weight keeps only known flag ids, unparseable JSON gives rejected', async () => {
  const { route } = fakeRoute();
  const d = await debate(input, { route });
  assert.equal(d.status, 'ok');
  assert.deepEqual(d.weight, ['top10_concentration', 'young_token']);
  assert.deepEqual(d.unknown, ['team wallets']);
  assert.equal(d.tension, REVIEW.tension);

  const fenced = fakeRoute({ reviewer: '```json\n' + JSON.stringify(REVIEW) + '\n```' });
  assert.equal((await debate(input, { route: fenced.route })).status, 'ok');

  for (const bad of ['not json', '{"text": 1}', '[]', JSON.stringify({ text: 'ok', weight: 'x', unknown: [] })]) {
    const r = fakeRoute({ reviewer: bad });
    const d2 = await debate(input, { route: r.route });
    assert.equal(d2.status, 'rejected', bad);
    assert.equal(d2.sound, '');
    assert.equal(d2.reviewer, '');
    assert.ok(d2.rejected.includes('reviewer: unparseable JSON'));
  }
});

test('A5 a call over timeoutMs gives status timeout without throwing', async () => {
  const slow = () => new Promise<RouteResult>((r) => setTimeout(() => r({ content: SOUND }), 200));
  const a = fakeRoute({ fragile: slow });
  const d = await debate(input, { route: a.route, timeoutMs: 30 });
  assert.equal(d.status, 'timeout');
  assert.equal(d.sound, '');
  assert.equal(d.fragile, '');
  assert.equal(a.calls.length, 2);

  const b = fakeRoute({ reviewer: slow });
  const d2 = await debate(input, { route: b.route, timeoutMs: 30 });
  assert.equal(d2.status, 'timeout');
  assert.equal(d2.reviewer, '');

  const never = fakeRoute({ reviewer: () => Promise.reject(new Error('boom')) });
  const d3 = await debate(input, { route: never.route });
  assert.equal(d3.status, 'rejected');
  assert.ok(d3.rejected.includes('reviewer: call failed'));
});

test('A6 mode off makes no call, shadow logs and returns shown false, on returns shown true, usd sums the calls', async () => {
  const off = fakeRoute();
  const d0 = await debate(input, { route: off.route, mode: 'off' });
  assert.equal(off.calls.length, 0);
  assert.equal(d0.status, 'off');
  assert.equal(d0.shown, false);

  const logged: object[] = [];
  const sh = fakeRoute();
  const d1 = await debate(input, { route: sh.route, log: (row) => logged.push(row) });
  assert.equal(sh.calls.length, 3);
  assert.equal(d1.status, 'ok');
  assert.equal(d1.shown, false);
  assert.equal(logged.length, 1);
  assert.deepEqual(logged[0], d1);

  const on = fakeRoute();
  const d2 = await debate(input, { route: on.route, mode: 'on', log: () => assert.fail('on does not log') });
  assert.equal(d2.shown, true);
  assert.equal(Math.round(d2.usd * 1000), 30);
  assert.deepEqual(d2.models, { sound: 'model-sound', fragile: 'model-fragile', reviewer: 'model-reviewer' });
  // the debate never returns or changes a level or points
  assert.equal('level' in d2, false);
  assert.equal('points' in d2, false);
  assert.equal(input.level, 'medium');
  assert.equal(input.points, 46);
});

test('A7 the README shows the call flow, the rules, an example Debate and credits TradingAgents', () => {
  const readme = readFileSync(new URL('../README.md', import.meta.url), 'utf8');
  for (const s of ['## Call flow', '## Rules', '## Example Debate', 'TradingAgents', 'TauricResearch', 'Apache 2.0']) {
    assert.ok(readme.includes(s), s);
  }
  const example = readme.split('## Example Debate')[1].match(/```json\n([\s\S]*?)```/);
  assert.ok(example);
  const parsed = JSON.parse(example[1]);
  assert.equal(parsed.status, 'ok');
  assert.ok(!/[–—]/.test(readme), 'no long dash in the README');
});
