// x402 paid agent starter: one route priced in USDC (exact scheme, version 1 headers).
// Web standard fetch handler, so it runs on Node, Hono, Bun or a worker.

export type Network = "base" | "base-sepolia";

export const USDC: Record<Network, string> = {
  base: "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913",
  "base-sepolia": "0x036CbD53842c5426634e7929541eC2318f3dCF7e",
};

// EIP-712 domain of the USDC contract, needed by payers to sign EIP-3009.
const USDC_DOMAIN: Record<Network, { name: string; version: string }> = {
  base: { name: "USD Coin", version: "2" },
  "base-sepolia": { name: "USDC", version: "2" },
};

export interface PaymentRequirements {
  scheme: "exact";
  network: Network;
  maxAmountRequired: string;
  resource: string;
  description: string;
  mimeType: string;
  payTo: string;
  maxTimeoutSeconds: number;
  asset: string;
  extra: { name: string; version: string };
}

export interface PaymentPayload {
  x402Version: number;
  scheme: string;
  network: string;
  payload: unknown;
}

export interface VerifyResult { isValid: boolean; invalidReason?: string }
export interface SettleResult { success: boolean; transaction: string; network: string; errorReason?: string }

export interface Facilitator {
  verify(paymentPayload: PaymentPayload, paymentRequirements: PaymentRequirements): Promise<VerifyResult>;
  settle(paymentPayload: PaymentPayload, paymentRequirements: PaymentRequirements): Promise<SettleResult>;
}

export interface AppOptions {
  price: string;
  payTo: string;
  network: Network;
  facilitator?: Facilitator | string;
  description?: string;
  maxTimeoutSeconds?: number;
  work?: (request: Request) => Promise<unknown> | unknown;
}

export const DEFAULT_FACILITATOR_URL = "https://x402.org/facilitator";

// "0.01" -> "10000" (USDC has 6 decimals). Exact decimal arithmetic, no floats.
export function toAtomic(price: string): string {
  const m = /^(\d+)(?:\.(\d{1,6}))?$/.exec(price.trim());
  if (!m) throw new Error(`price must be a decimal USDC string with at most 6 decimals, got "${price}"`);
  const atomic = BigInt(m[1]) * 1_000_000n + BigInt((m[2] ?? "").padEnd(6, "0"));
  if (atomic <= 0n) throw new Error("price must be above zero");
  return atomic.toString();
}

const b64encode = (v: unknown) => Buffer.from(JSON.stringify(v), "utf8").toString("base64");
const b64decode = (s: string): unknown => JSON.parse(Buffer.from(s, "base64").toString("utf8"));

// Facilitator over HTTP: POST <url>/verify and <url>/settle with {x402Version, paymentPayload, paymentRequirements}.
export function httpFacilitator(url: string, fetchFn: typeof fetch = fetch): Facilitator {
  const base = url.replace(/\/+$/, "");
  const call = async (path: string, paymentPayload: PaymentPayload, paymentRequirements: PaymentRequirements) => {
    const res = await fetchFn(`${base}/${path}`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ x402Version: 1, paymentPayload, paymentRequirements }),
    });
    if (!res.ok) throw new Error(`facilitator ${path} answered HTTP ${res.status}`);
    return res.json();
  };
  return {
    verify: (p, r) => call("verify", p, r) as Promise<VerifyResult>,
    settle: (p, r) => call("settle", p, r) as Promise<SettleResult>,
  };
}

const json = (status: number, body: unknown, headers: Record<string, string> = {}) =>
  new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", ...headers } });

export function createApp(opts: AppOptions): { fetch(request: Request): Promise<Response> } {
  if (!(opts.network in USDC)) throw new Error(`network must be base or base-sepolia, got "${opts.network}"`);
  if (!/^0x[0-9a-fA-F]{40}$/.test(opts.payTo)) throw new Error("payTo must be an EVM address");
  const amount = toAtomic(opts.price);
  const facilitator: Facilitator =
    typeof opts.facilitator === "object" ? opts.facilitator : httpFacilitator(opts.facilitator ?? DEFAULT_FACILITATOR_URL);
  const description = opts.description ?? "One paid call to this agent";
  const work = opts.work ?? (() => ({ ok: true, message: "Paid work done. Thank you." }));

  const requirementsFor = (request: Request): PaymentRequirements => {
    const u = new URL(request.url);
    return {
      scheme: "exact",
      network: opts.network,
      maxAmountRequired: amount,
      resource: `${u.origin}${u.pathname}`,
      description,
      mimeType: "application/json",
      payTo: opts.payTo,
      maxTimeoutSeconds: opts.maxTimeoutSeconds ?? 60,
      asset: USDC[opts.network],
      extra: USDC_DOMAIN[opts.network],
    };
  };
  const paymentRequired = (req: PaymentRequirements, error: string) =>
    json(402, { x402Version: 1, error, accepts: [req] });

  return {
    async fetch(request: Request): Promise<Response> {
      const { pathname } = new URL(request.url);
      if (pathname === "/health") return json(200, { ok: true });
      if (pathname !== "/paid") return json(404, { error: "not found" });
      if (request.method !== "GET") return json(405, { error: "method not allowed" }, { allow: "GET" });

      const req = requirementsFor(request);
      const header = request.headers.get("x-payment");
      if (!header) return paymentRequired(req, "X-PAYMENT header is required");

      let payload: PaymentPayload;
      try {
        payload = b64decode(header) as PaymentPayload;
        if (!payload || typeof payload !== "object") throw new Error("not an object");
      } catch {
        return paymentRequired(req, "X-PAYMENT is not base64 encoded JSON");
      }
      if (payload.scheme !== "exact" || payload.network !== opts.network) {
        return paymentRequired(req, `payment must use scheme exact on ${opts.network}`);
      }

      try {
        const v = await facilitator.verify(payload, req);
        if (!v?.isValid) return paymentRequired(req, `payment did not verify: ${v?.invalidReason ?? "invalid"}`);
        const s = await facilitator.settle(payload, req);
        if (!s?.success) return paymentRequired(req, `payment did not settle: ${s?.errorReason ?? "failed"}`);
        // Work runs only after a successful settlement.
        const result = await work(request);
        return json(200, result, { "x-payment-response": b64encode(s) });
      } catch (e) {
        return paymentRequired(req, `facilitator error: ${(e as Error).message}`);
      }
    },
  };
}
