// List a LAX offer on the registry, answering its x402 402 with a payment from the caller.
// The key stays with the caller: pay() gets the payment terms and returns the header value.

export interface PaymentRequired {
  x402Version: number;
  accepts?: unknown[];
  accepts_v1?: unknown[];
  [k: string]: unknown;
}

export interface ListOptions {
  offer: Record<string, unknown>;
  registryUrl?: string;
  fetch?: typeof fetch;
  pay: (paymentRequired: PaymentRequired) => Promise<string> | string;
}

export const DEFAULT_REGISTRY = "https://lax.kognai.ai/registry";

async function readJson(res: Response): Promise<any> {
  const text = await res.text();
  try { return text ? JSON.parse(text) : {}; } catch { return { error: text.slice(0, 200) }; }
}

export async function listOffer({ offer, registryUrl = DEFAULT_REGISTRY, fetch: fetchFn = fetch, pay }: ListOptions): Promise<{ id: string }> {
  const url = `${registryUrl.replace(/\/+$/, "")}/offers`;
  const body = JSON.stringify(offer);
  const post = (headers: Record<string, string> = {}) =>
    fetchFn(url, { method: "POST", headers: { "content-type": "application/json", ...headers }, body });

  let res = await post();
  if (res.status === 402) {
    const terms = (await readJson(res)) as PaymentRequired;
    if (terms.x402Version !== 1 && terms.x402Version !== 2) {
      throw new Error("registry answered 402 without x402 payment terms");
    }
    const value = await pay(terms);
    // A version 2 payment payload goes in PAYMENT-SIGNATURE, a version 1 payload in X-PAYMENT.
    res = await post({ [payloadVersion(value) === 2 ? "PAYMENT-SIGNATURE" : "X-PAYMENT"]: value });
  }
  const data = await readJson(res);
  if (!res.ok) throw new Error(`registry answered HTTP ${res.status}: ${String(data.error ?? "listing refused").slice(0, 300)}`);
  if (typeof data.id !== "string" || !data.id) throw new Error("registry answer has no listing id");
  return { id: data.id };
}

// The x402Version inside the base64 JSON payment payload, 1 when it cannot be read.
function payloadVersion(value: string): number {
  try { return JSON.parse(Buffer.from(value, "base64").toString("utf8")).x402Version === 2 ? 2 : 1; } catch { return 1; }
}
