// Payer side of the x402 exact scheme on Base: sign an EIP-3009 transferWithAuthorization
// for one set of payment requirements and return the X-PAYMENT header value.
import { randomBytes } from "node:crypto";
import type { LocalAccount } from "viem";

const CHAIN_ID: Record<string, number> = { base: 8453, "base-sepolia": 84532 };

export interface ExactRequirements {
  network: string;
  maxAmountRequired: string;
  payTo: string;
  asset: string;
  maxTimeoutSeconds?: number;
  extra?: { name?: string; version?: string };
}

export async function createPaymentHeader(account: LocalAccount, req: ExactRequirements, now = Math.floor(Date.now() / 1000)): Promise<string> {
  const chainId = CHAIN_ID[req.network];
  if (!chainId) throw new Error(`unsupported network ${req.network}`);
  const authorization = {
    from: account.address,
    to: req.payTo as `0x${string}`,
    value: BigInt(req.maxAmountRequired),
    validAfter: BigInt(now - 60),
    validBefore: BigInt(now + (req.maxTimeoutSeconds ?? 60)),
    nonce: `0x${randomBytes(32).toString("hex")}` as `0x${string}`,
  };
  const signature = await account.signTypedData({
    domain: { name: req.extra?.name ?? "USD Coin", version: req.extra?.version ?? "2", chainId, verifyingContract: req.asset as `0x${string}` },
    types: {
      TransferWithAuthorization: [
        { name: "from", type: "address" }, { name: "to", type: "address" }, { name: "value", type: "uint256" },
        { name: "validAfter", type: "uint256" }, { name: "validBefore", type: "uint256" }, { name: "nonce", type: "bytes32" },
      ],
    },
    primaryType: "TransferWithAuthorization",
    message: authorization,
  });
  const payload = {
    x402Version: 1,
    scheme: "exact",
    network: req.network,
    payload: { signature, authorization: Object.fromEntries(Object.entries(authorization).map(([k, v]) => [k, String(v)])) },
  };
  return Buffer.from(JSON.stringify(payload), "utf8").toString("base64");
}

// Pick the version 1 Base terms out of a 402 body (plain v1, or the registry's v2 body with accepts_v1).
export function pickV1Requirements(body: any, network = "base"): ExactRequirements {
  const list = body?.x402Version === 1 ? body.accepts : body?.accepts_v1 ?? body?.x402_v1?.accepts;
  const req = (list ?? []).find((a: any) => a?.scheme === "exact" && a?.network === network);
  if (!req) throw new Error(`no exact ${network} terms in the 402 answer`);
  return req;
}
