// Local check of a LAX offer against https://lax.kognai.ai/aiax/sections/lax_offer.json,
// so a broken offer is caught before paying the listing fee.

export const FIVE_LAWS = ["Solidarity Oath", "Renewal Mandate", "Treasury Equilibrium", "Harm Shield", "Transparency Covenant"];

const isHttps = (v: unknown) => { try { return typeof v === "string" && new URL(v).protocol === "https:"; } catch { return false; } };

export function validateOffer(o: any): string[] {
  const errors: string[] = [];
  if (!o || typeof o !== "object") return ["offer must be an object"];
  if (o.lax_version !== undefined && o.lax_version !== "1.0") errors.push("lax_version must be 1.0");
  if (typeof o.name !== "string" || o.name.length < 3 || o.name.length > 80) errors.push("name must be 3 to 80 characters");
  if (typeof o.description !== "string" || o.description.length < 20 || o.description.length > 600) errors.push("description must be 20 to 600 characters");
  if (o.category !== undefined && (typeof o.category !== "string" || o.category.length < 2 || o.category.length > 40)) errors.push("category must be 2 to 40 characters");
  if (o.endpoint === undefined && o.pact_endpoint === undefined) errors.push("endpoint or pact_endpoint is required");
  for (const k of ["endpoint", "pact_endpoint"]) if (o[k] !== undefined && !isHttps(o[k])) errors.push(`${k} must be an https url`);
  if (!Array.isArray(o.capabilities) || o.capabilities.length < 1 || o.capabilities.length > 10) errors.push("capabilities must hold 1 to 10 items");
  else o.capabilities.forEach((c: any, i: number) => {
    if (typeof c?.skill_id !== "string" || !c.skill_id) errors.push(`capabilities[${i}].skill_id is required`);
    if (typeof c?.description !== "string" || !c.description) errors.push(`capabilities[${i}].description is required`);
    const p = c?.pricing ?? {};
    if (!["per_call", "per_minute", "flat", "free"].includes(p.model)) errors.push(`capabilities[${i}].pricing.model must be per_call, per_minute, flat or free`);
    if (p.model !== "free" && !/^\d+(\.\d{1,6})?$/.test(String(p.amount ?? ""))) errors.push(`capabilities[${i}].pricing.amount must be a decimal string like "0.05"`);
    if (p.currency !== "USDC") errors.push(`capabilities[${i}].pricing.currency must be USDC`);
    if (p.rail !== "x402") errors.push(`capabilities[${i}].pricing.rail must be x402`);
  });
  const cc = Array.isArray(o.constitutional_constraints) ? o.constitutional_constraints : [];
  for (const law of FIVE_LAWS) if (!cc.includes(law)) errors.push(`constitutional_constraints must include ${law}`);
  if (o.payment_rails !== undefined && (!Array.isArray(o.payment_rails) || o.payment_rails.some((r: unknown) => !["x402", "usdc", "usdc-base"].includes(r as string)))) errors.push("payment_rails may hold x402, usdc or usdc-base");
  return errors;
}
