// A facilitator that checks the EIP-3009 signature locally and records each call.
function localFacilitator(opts: { settleOk?: boolean; verifyOk?: boolean } = {}) {
  const calls: string[] = [];
  const f: Facilitator = {
    async verify(p: any, r: PaymentRequirements) {
      calls.push("verify");
      if (opts.verifyOk === false) return { isValid: false, invalidReason: "insufficient_funds" };
      const a = p.payload.authorization;
      const ok = await verifyTypedData({
        address: a.from,
        domain: { name: r.extra.name, version: r.extra.version, chainId: r.network === "base" ? 8453 : 84532, verifyingContract: r.asset as `0x${string}` },
        types: { TransferWithAuthorization: [
