        message: { from: a.from, to: a.to, value: BigInt(a.value), validAfter: BigInt(a.validAfter), validBefore: BigInt(a.validBefore), nonce: a.nonce },
        signature: p.payload.signature,
      });
      const right = ok && a.to.toLowerCase() === r.payTo.toLowerCase() && BigInt(a.value) >= BigInt(r.maxAmountRequired);
      return right ? { isValid: true } : { isValid: false, invalidReason: "invalid_exact_evm_payload_signature" };
