    async settle(_p, r) {
      calls.push("settle");
      if (opts.settleOk === false) return { success: false, transaction: "", network: r.network, errorReason: "transaction_failed" };
      return { success: true, transaction: "0x" + "ab".repeat(32), network: r.network };
    },
  };
  return { f, calls };
}

