"""x402 paid agent starter (Python, Flask): one route priced in USDC, exact scheme, version 1 headers.

Run: PAY_TO=0x.. PRICE=0.01 NETWORK=base-sepolia FACILITATOR_URL=https://x402.org/facilitator python app.py
"""
import base64
import json
import os
import re
from decimal import Decimal, InvalidOperation

import requests
from flask import Flask, Response, request

USDC = {
    "base": "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913",
    "base-sepolia": "0x036CbD53842c5426634e7929541eC2318f3dCF7e",
}
# EIP-712 domain of the USDC contract, needed by payers to sign EIP-3009.
USDC_DOMAIN = {"base": {"name": "USD Coin", "version": "2"}, "base-sepolia": {"name": "USDC", "version": "2"}}
DEFAULT_FACILITATOR_URL = "https://x402.org/facilitator"


def to_atomic(price: str) -> str:
    """'0.01' -> '10000' (USDC has 6 decimals), exact decimal arithmetic."""
    if not isinstance(price, str) or not re.fullmatch(r"\d+(\.\d{1,6})?", price.strip()):
        raise ValueError(f'price must be a decimal USDC string with at most 6 decimals, got "{price}"')
    try:
        atomic = int(Decimal(price.strip()) * 1_000_000)
    except InvalidOperation as e:
        raise ValueError(str(e)) from e
    if atomic <= 0:
        raise ValueError("price must be above zero")
    return str(atomic)


class HttpFacilitator:
    """POST <url>/verify and <url>/settle with {x402Version, paymentPayload, paymentRequirements}."""

    def __init__(self, url: str, session=None):
        self.url = url.rstrip("/")
        self.session = session or requests.Session()

    def _call(self, path, payload, req):
        r = self.session.post(f"{self.url}/{path}", json={"x402Version": 1, "paymentPayload": payload, "paymentRequirements": req}, timeout=30)
        if not r.ok:
            raise RuntimeError(f"facilitator {path} answered HTTP {r.status_code}")
        return r.json()

    def verify(self, payload, req):
        return self._call("verify", payload, req)

    def settle(self, payload, req):
        return self._call("settle", payload, req)


def _b64(v) -> str:
    return base64.b64encode(json.dumps(v, separators=(",", ":")).encode()).decode()


def create_app(price: str, pay_to: str, network: str, facilitator=None, description=None, max_timeout_seconds=60, work=None) -> Flask:
    if network not in USDC:
        raise ValueError(f'network must be base or base-sepolia, got "{network}"')
    if not re.fullmatch(r"0x[0-9a-fA-F]{40}", pay_to or ""):
        raise ValueError("pay_to must be an EVM address")
    amount = to_atomic(price)
    if facilitator is None or isinstance(facilitator, str):
        facilitator = HttpFacilitator(facilitator or DEFAULT_FACILITATOR_URL)
    description = description or "One paid call to this agent"
    work = work or (lambda: {"ok": True, "message": "Paid work done. Thank you."})
    app = Flask(__name__)

    def as_json(status, body, headers=None):
        return Response(json.dumps(body), status=status, mimetype="application/json", headers=headers or {})

    def requirements():
        return {
            "scheme": "exact",
            "network": network,
            "maxAmountRequired": amount,
            "resource": request.base_url,
            "description": description,
            "mimeType": "application/json",
            "payTo": pay_to,
            "maxTimeoutSeconds": max_timeout_seconds,
            "asset": USDC[network],
            "extra": USDC_DOMAIN[network],
        }

    def payment_required(req, error):
        return as_json(402, {"x402Version": 1, "error": error, "accepts": [req]})

    @app.get("/health")
    def health():
        return as_json(200, {"ok": True})

    @app.get("/paid")
    def paid():
        req = requirements()
        header = request.headers.get("X-PAYMENT")
        if not header:
            return payment_required(req, "X-PAYMENT header is required")
        try:
            payload = json.loads(base64.b64decode(header, validate=True))
            if not isinstance(payload, dict):
                raise ValueError("not an object")
        except Exception:
            return payment_required(req, "X-PAYMENT is not base64 encoded JSON")
        if payload.get("scheme") != "exact" or payload.get("network") != network:
            return payment_required(req, f"payment must use scheme exact on {network}")
        try:
            v = facilitator.verify(payload, req) or {}
            if not v.get("isValid"):
                return payment_required(req, f"payment did not verify: {v.get('invalidReason') or 'invalid'}")
            s = facilitator.settle(payload, req) or {}
            if not s.get("success"):
                return payment_required(req, f"payment did not settle: {s.get('errorReason') or 'failed'}")
        except Exception as e:
            return payment_required(req, f"facilitator error: {e}")
        # Work runs only after a successful settlement.
        return as_json(200, work(), {"X-PAYMENT-RESPONSE": _b64(s)})

    return app


if __name__ == "__main__":
    create_app(
        price=os.environ.get("PRICE", "0.01"),
        pay_to=os.environ.get("PAY_TO", ""),
        network=os.environ.get("NETWORK", "base-sepolia"),
        facilitator=os.environ.get("FACILITATOR_URL"),
    ).run(port=int(os.environ.get("PORT", "8402")))
