"""Payer side of the x402 exact scheme on Base: sign an EIP-3009 transferWithAuthorization."""
import base64
import json
import secrets
import time

from eth_account.messages import encode_typed_data

CHAIN_ID = {"base": 8453, "base-sepolia": 84532}
_TYPES = {
    "EIP712Domain": [{"name": "name", "type": "string"}, {"name": "version", "type": "string"},
                     {"name": "chainId", "type": "uint256"}, {"name": "verifyingContract", "type": "address"}],
    "TransferWithAuthorization": [{"name": "from", "type": "address"}, {"name": "to", "type": "address"},
                                  {"name": "value", "type": "uint256"}, {"name": "validAfter", "type": "uint256"},
                                  {"name": "validBefore", "type": "uint256"}, {"name": "nonce", "type": "bytes32"}],
}


def typed_data(req: dict, auth: dict) -> dict:
    extra = req.get("extra") or {}
    return {"types": _TYPES, "primaryType": "TransferWithAuthorization",
            "domain": {"name": extra.get("name", "USD Coin"), "version": extra.get("version", "2"),
                       "chainId": CHAIN_ID[req["network"]], "verifyingContract": req["asset"]},
            "message": {**auth, "value": int(auth["value"]), "validAfter": int(auth["validAfter"]), "validBefore": int(auth["validBefore"])}}


def create_payment_header(account, req: dict, now: int | None = None) -> str:
    if req.get("network") not in CHAIN_ID:
        raise ValueError(f"unsupported network {req.get('network')}")
    now = int(time.time()) if now is None else now
    auth = {"from": account.address, "to": req["payTo"], "value": str(int(req["maxAmountRequired"])),
            "validAfter": str(now - 60), "validBefore": str(now + int(req.get("maxTimeoutSeconds", 60))),
            "nonce": "0x" + secrets.token_hex(32)}
    sig = account.sign_message(encode_typed_data(full_message=typed_data(req, auth))).signature.hex()
    payload = {"x402Version": 1, "scheme": "exact", "network": req["network"],
               "payload": {"signature": sig if sig.startswith("0x") else "0x" + sig, "authorization": auth}}
    return base64.b64encode(json.dumps(payload).encode()).decode()


def pick_v1_requirements(body: dict, network: str = "base") -> dict:
    """The version 1 terms from a 402 body (plain v1, or the registry's v2 body with accepts_v1)."""
    items = body.get("accepts") if body.get("x402Version") == 1 else body.get("accepts_v1") or (body.get("x402_v1") or {}).get("accepts")
    for a in items or []:
        if a.get("scheme") == "exact" and a.get("network") == network:
            return a
    raise ValueError(f"no exact {network} terms in the 402 answer")
