"""List a LAX offer on the registry, answering its x402 402 with a payment from the caller.

Run: PAYER_KEY=0x.. python list_offer.py   (the key is read from the environment and never printed)
"""
import base64
import json
import os
import re
import sys

import requests

DEFAULT_REGISTRY = "https://lax.kognai.ai/registry"
FIVE_LAWS = ["Solidarity Oath", "Renewal Mandate", "Treasury Equilibrium", "Harm Shield", "Transparency Covenant"]


def _https(v):
    return isinstance(v, str) and re.match(r"^https://[^\s/]+", v) is not None


def validate_offer(o) -> list[str]:
    """Local check against https://lax.kognai.ai/aiax/sections/lax_offer.json, before paying the fee."""
    if not isinstance(o, dict):
        return ["offer must be an object"]
    e = []
    if "lax_version" in o and o["lax_version"] != "1.0":
        e.append("lax_version must be 1.0")
    if not isinstance(o.get("name"), str) or not 3 <= len(o["name"]) <= 80:
        e.append("name must be 3 to 80 characters")
    if not isinstance(o.get("description"), str) or not 20 <= len(o["description"]) <= 600:
        e.append("description must be 20 to 600 characters")
    if "category" in o and not (isinstance(o["category"], str) and 2 <= len(o["category"]) <= 40):
        e.append("category must be 2 to 40 characters")
    if "endpoint" not in o and "pact_endpoint" not in o:
        e.append("endpoint or pact_endpoint is required")
    for k in ("endpoint", "pact_endpoint"):
        if k in o and not _https(o[k]):
            e.append(f"{k} must be an https url")
    caps = o.get("capabilities")
    if not isinstance(caps, list) or not 1 <= len(caps) <= 10:
        e.append("capabilities must hold 1 to 10 items")
    else:
        for i, c in enumerate(caps):
            p = (c or {}).get("pricing") or {}
            if not (c or {}).get("skill_id"):
                e.append(f"capabilities[{i}].skill_id is required")
            if not (c or {}).get("description"):
                e.append(f"capabilities[{i}].description is required")
            if p.get("model") not in ("per_call", "per_minute", "flat", "free"):
                e.append(f"capabilities[{i}].pricing.model must be per_call, per_minute, flat or free")
            if p.get("model") != "free" and not re.fullmatch(r"\d+(\.\d{1,6})?", str(p.get("amount", ""))):
                e.append(f'capabilities[{i}].pricing.amount must be a decimal string like "0.05"')
            if p.get("currency") != "USDC":
                e.append(f"capabilities[{i}].pricing.currency must be USDC")
            if p.get("rail") != "x402":
                e.append(f"capabilities[{i}].pricing.rail must be x402")
    cc = o.get("constitutional_constraints") if isinstance(o.get("constitutional_constraints"), list) else []
    e += [f"constitutional_constraints must include {law}" for law in FIVE_LAWS if law not in cc]
    return e


def _payload_version(value: str) -> int:
    try:
        return 2 if json.loads(base64.b64decode(value)).get("x402Version") == 2 else 1
    except Exception:
        return 1


def list_offer(offer: dict, pay, registry_url: str = DEFAULT_REGISTRY, session=None) -> dict:
    """POST <registry>/offers; on 402 call pay(terms) for the header value and post again. Returns {"id": ...}."""
    s = session or requests.Session()
    url = registry_url.rstrip("/") + "/offers"
    r = s.post(url, json=offer, timeout=60)
    if r.status_code == 402:
        terms = r.json()
        if terms.get("x402Version") not in (1, 2):
            raise RuntimeError("registry answered 402 without x402 payment terms")
        value = pay(terms)
        header = "PAYMENT-SIGNATURE" if _payload_version(value) == 2 else "X-PAYMENT"
        r = s.post(url, json=offer, headers={header: value}, timeout=60)
    try:
        data = r.json()
    except ValueError:
        data = {"error": r.text[:200]}
    if not r.ok:
        raise RuntimeError(f"registry answered HTTP {r.status_code}: {str(data.get('error', 'listing refused'))[:300]}")
    if not data.get("id"):
        raise RuntimeError("registry answer has no listing id")
    return {"id": data["id"]}


def main():
    from eth_account import Account
    from exact import create_payment_header, pick_v1_requirements

    with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "lax-offer.json")) as f:
        offer = json.load(f)
    errors = validate_offer(offer)
    if errors:
        sys.exit("\n".join(errors))
    if not os.environ.get("PAYER_KEY"):
        sys.exit("set PAYER_KEY")
    account = Account.from_key(os.environ["PAYER_KEY"])
    listing = list_offer(offer, lambda t: create_payment_header(account, pick_v1_requirements(t, "base")))
    print("listed:", listing["id"])


if __name__ == "__main__":
    main()
