// ERC-8004 identity viewer: reads an agent's identity (owner, tokenURI, registration file)
// and its reputation feedback. Plain ES module, no dependency: runs in the browser and in Node 20.
import { REGISTRIES, NETWORKS, IPFS_GATEWAY } from "./config.js";

export { REGISTRIES, NETWORKS };

const SEL = {
  ownerOf: "6352211e", // ownerOf(uint256)
  tokenURI: "c87b56dd", // tokenURI(uint256)
  getClients: "42dd519c", // getClients(uint256)
  readAllFeedback: "d9d84224", // readAllFeedback(uint256,address[],string,string,bool)
};
const ZERO_ADDR = "0x" + "0".repeat(40);
const MAX_UINT256 = (1n << 256n) - 1n;
export const LATEST = 10;

const hexToBytes = (h) => {
  const out = new Uint8Array(h.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(h.slice(i * 2, i * 2 + 2), 16);
  return out;
};
const word = (v) => BigInt(v).toString(16).padStart(64, "0");
const addrWord = (a) => a.toLowerCase().replace(/^0x/, "").padStart(64, "0");

// Strict ABI reader over a hex string without 0x: every offset and length is bounds checked.
function reader(h) {
  const words = h.length / 2;
  const w = (o) => {
    if (o < 0 || o * 2 + 64 > h.length) throw new Error("malformed return data");
    return h.slice(o * 2, o * 2 + 64);
  };
  const num = (o) => {
    const v = BigInt("0x" + w(o));
    if (v > BigInt(words)) throw new Error("malformed return data");
    return Number(v);
  };
  const str = (o) => {
    const len = num(o), s = (o + 32) * 2;
    if (s + len * 2 > h.length) throw new Error("malformed return data");
    return new TextDecoder("utf-8", { fatal: true }).decode(hexToBytes(h.slice(s, s + len * 2)));
  };
  const arr = (o, item) => {
    const n = num(o), out = [];
    for (let i = 0; i < n; i++) out.push(item(o + 32, o + 32 + 32 * i));
    return out;
  };
  return { w, num, str, arr };
}
const clean = (ret) => {
  const h = String(ret ?? "").replace(/^0x/, "").toLowerCase();
  if (!/^[0-9a-f]*$/.test(h) || h.length % 64 !== 0) throw new Error("malformed return data");
  return h;
};
const int128 = (hex) => {
  let v = BigInt("0x" + hex);
  if (v >= 1n << 255n) v -= 1n << 256n;
  return v;
};

export const decodeAddress = (ret) => {
  const h = clean(ret);
  if (h.length < 64) throw new Error("malformed return data");
  return "0x" + h.slice(24, 64);
};
export const decodeString = (ret) => {
  const h = clean(ret);
  const r = reader(h);
  return r.str(r.num(0));
};
export const decodeAddressArray = (ret) => {
  const r = reader(clean(ret));
  return r.arr(r.num(0), (_base, at) => "0x" + r.w(at).slice(24));
};

// readAllFeedback returns (address[] clients, uint64[] indexes, int128[] values, uint8[] decimals,
// string[] tag1s, string[] tag2s, bool[] revoked), all parallel arrays.
export function decodeFeedback(ret) {
  const r = reader(clean(ret));
  const head = (i) => r.num(32 * i);
  const clients = r.arr(head(0), (_b, at) => "0x" + r.w(at).slice(24));
  const indexes = r.arr(head(1), (_b, at) => Number(BigInt("0x" + r.w(at))));
  const values = r.arr(head(2), (_b, at) => int128(r.w(at)));
  const decimals = r.arr(head(3), (_b, at) => Number(BigInt("0x" + r.w(at))));
  const tag1s = r.arr(head(4), (b, at) => r.str(b + r.num(at)));
  const tag2s = r.arr(head(5), (b, at) => r.str(b + r.num(at)));
  const revoked = r.arr(head(6), (_b, at) => BigInt("0x" + r.w(at)) !== 0n);
  const n = clients.length;
  if ([indexes, values, decimals, tag1s, tag2s, revoked].some((a) => a.length !== n)) throw new Error("malformed return data");
  return clients.map((client, i) => ({ client, index: indexes[i], value: values[i], decimals: decimals[i], tag1: tag1s[i], tag2: tag2s[i], revoked: revoked[i] }));
}

export const encodeCall = {
  ownerOf: (id) => "0x" + SEL.ownerOf + word(id),
  tokenURI: (id) => "0x" + SEL.tokenURI + word(id),
  getClients: (id) => "0x" + SEL.getClients + word(id),
  readAllFeedback: (id, clients) => {
    const arrOff = 5 * 32, t1Off = arrOff + 32 + 32 * clients.length, t2Off = t1Off + 32;
    return "0x" + SEL.readAllFeedback + word(id) + word(arrOff) + word(t1Off) + word(t2Off) + word(0) +
      word(clients.length) + clients.map(addrWord).join("") + word(0) + word(0);
  },
};

// Score as a decimal string: value / 10^decimals, exact (no float rounding on the way).
export function formatScore(value, decimals) {
  const neg = value < 0n, abs = neg ? -value : value;
  const s = abs.toString().padStart(decimals + 1, "0");
  const int = s.slice(0, s.length - decimals), frac = decimals ? s.slice(s.length - decimals).replace(/0+$/, "") : "";
  return (neg ? "-" : "") + int + (frac ? "." + frac : "");
}

export function summarise(entries, latest = LATEST) {
  const live = entries.filter((e) => !e.revoked);
  const items = live.map((e) => ({ client: e.client, index: e.index, score: Number(formatScore(e.value, e.decimals)), tags: [e.tag1, e.tag2].filter(Boolean) }));
  const count = items.length;
  const average = count ? Math.round((items.reduce((s, x) => s + x.score, 0) / count) * 100) / 100 : null;
  return { count, average, items: items.slice(-latest).reverse() };
}

// tokenURI -> URL to fetch, or the decoded JSON for data: URIs (no request).
export function resolveURI(uri, gateway = IPFS_GATEWAY) {
  const u = String(uri).trim();
  if (u.startsWith("ipfs://")) return { url: gateway + u.slice(7).replace(/^ipfs\//, "") };
  if (/^data:/i.test(u)) {
    const comma = u.indexOf(",");
    if (comma < 0) throw new Error("the data: URI has no payload");
    const meta = u.slice(5, comma).toLowerCase(), body = u.slice(comma + 1);
    if (!/^application\/json/.test(meta)) throw new Error("the data: URI is not application/json");
    let text;
    if (/;base64$/.test(meta)) {
      const bin = atob(body.replace(/\s/g, ""));
      text = new TextDecoder("utf-8", { fatal: true }).decode(Uint8Array.from(bin, (c) => c.charCodeAt(0)));
    } else text = decodeURIComponent(body);
    try { return { json: JSON.parse(text) }; } catch { throw new Error("the data: URI does not hold valid JSON"); }
  }
  if (/^https?:\/\//i.test(u)) return { url: u };
  throw new Error("unsupported tokenURI scheme: " + (u.split(":")[0] || "empty"));
}

// Keeps the fields the page shows; endpoints accepts the registration-v1 "endpoints" and the later "services".
export function normaliseRegistration(j) {
  if (!j || typeof j !== "object" || Array.isArray(j)) throw new Error("the registration file is not a JSON object");
  const eps = Array.isArray(j.endpoints) ? j.endpoints : Array.isArray(j.services) ? j.services : [];
  return {
    name: typeof j.name === "string" ? j.name : null,
    description: typeof j.description === "string" ? j.description : null,
    image: typeof j.image === "string" ? j.image : null,
    endpoints: eps.filter((e) => e && typeof e === "object").map((e) => ({ name: String(e.name ?? e.type ?? ""), endpoint: String(e.endpoint ?? e.url ?? ""), version: e.version != null ? String(e.version) : null })),
    supportedTrust: Array.isArray(j.supportedTrust) ? j.supportedTrust.map(String) : [],
    raw: j,
  };
}

const isRevert = (e) => e && (e.code === 3 || /revert/i.test(String(e.message)));

// Default transports, used by the page. rpc throws an Error carrying code and message.
export function httpRpc(url, fetchImpl = globalThis.fetch) {
  let id = 0;
  return async (method, params) => {
    const res = await fetchImpl(url, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ jsonrpc: "2.0", id: ++id, method, params }) });
    if (!res.ok) throw Object.assign(new Error("RPC HTTP " + res.status), { code: res.status });
    const d = await res.json();
    if (d.error) throw Object.assign(new Error(d.error.message || "RPC error"), { code: d.error.code, data: d.error.data });
    return d.result;
  };
}
export function httpFetchJson(fetchImpl = globalThis.fetch) {
  return async (url) => {
    const res = await fetchImpl(url, { headers: { accept: "application/json" } });
    if (!res.ok) throw new Error("HTTP " + res.status);
    return await res.json();
  };
}

export async function loadAgent({ agentId, network, identityRegistry, reputationRegistry, rpc, fetchJson, latest = LATEST } = {}) {
  const out = { status: "error", agentId: null, owner: null, tokenURI: null, registration: null, feedback: null };
  const fail = (msg) => ({ ...out, status: "error", error: msg });
  let id;
  try { id = BigInt(String(agentId ?? "").trim()); } catch { return fail("agentId must be a whole number"); }
  if (id < 0n || id > MAX_UINT256) return fail("agentId must be a whole number");
  out.agentId = id.toString();
  if (network != null && !NETWORKS[network]) return fail("unknown network: " + network);
  const reg = network ? REGISTRIES[network] : null;
  identityRegistry = identityRegistry ?? reg?.identity;
  if (!/^0x[0-9a-fA-F]{40}$/.test(String(identityRegistry))) return fail("identity registry address missing or invalid");
  if (typeof rpc !== "function") return fail("no rpc function given");
  const call = (data, to = identityRegistry) => rpc("eth_call", [{ to, data }, "latest"]);

  try {
    let owner;
    try { owner = decodeAddress(await call(encodeCall.ownerOf(id))); }
    catch (e) { if (isRevert(e)) return { ...out, status: "empty" }; throw e; }
    if (owner === ZERO_ADDR) return { ...out, status: "empty" };
    out.owner = owner;
    out.tokenURI = decodeString(await call(encodeCall.tokenURI(id)));
  } catch (e) {
    return fail("could not read the identity registry: " + (e?.message || String(e)));
  }

  try {
    if (!out.tokenURI) throw new Error("the agent has an empty tokenURI");
    const r = resolveURI(out.tokenURI);
    let json = r.json;
    if (r.url) {
      if (typeof fetchJson !== "function") throw new Error("no fetchJson function given");
      json = await fetchJson(r.url);
    }
    out.registration = normaliseRegistration(json);
  } catch (e) {
    return fail("could not read the registration file: " + (e?.message || String(e)));
  }

  if (reputationRegistry) {
    try {
      const clients = decodeAddressArray(await call(encodeCall.getClients(id), reputationRegistry));
      const entries = clients.length ? decodeFeedback(await call(encodeCall.readAllFeedback(id, clients), reputationRegistry)) : [];
      out.feedback = summarise(entries, latest);
    } catch (e) {
      return fail("could not read the reputation registry: " + (e?.message || String(e)));
    }
  }
  return { ...out, status: "ok" };
}
