// Turns a loadAgent result into HTML for the page. Pure function: testable in Node.
import { IPFS_GATEWAY, NETWORKS } from "./config.js";

const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const short = (a) => (a && a.length > 14 ? a.slice(0, 8) + "..." + a.slice(-6) : a);

// Only http(s) and ipfs images are shown; ipfs goes through the gateway.
export function imageURL(src, gateway = IPFS_GATEWAY) {
  const s = String(src ?? "").trim();
  if (s.startsWith("ipfs://")) return gateway + s.slice(7).replace(/^ipfs\//, "");
  if (/^https:\/\//i.test(s)) return s;
  if (/^data:image\/(png|jpeg|gif|webp);base64,/i.test(s)) return s;
  return null;
}
const link = (href, text) => (/^https?:\/\//i.test(href) ? `<a href="${esc(href)}" rel="noopener noreferrer" target="_blank">${esc(text)}</a>` : esc(text));

export function renderAgent(r, network) {
  const net = NETWORKS[network];
  if (!r || r.status === "error") return `<section class="state error" role="alert"><h2>Could not load agent ${esc(r?.agentId ?? "")}</h2><p>${esc(r?.error ?? "Unknown error")}</p></section>`;
  if (r.status === "empty") return `<section class="state empty"><h2>No agent ${esc(r.agentId)}</h2><p>No agent with this id is registered on ${esc(network)}.</p></section>`;
  const g = r.registration ?? {};
  const img = imageURL(g.image);
  const owner = net ? link(`${net.explorer}/address/${r.owner}`, r.owner) : esc(r.owner);
  const eps = g.endpoints?.length
    ? `<ul class="endpoints">${g.endpoints.map((e) => `<li><b>${esc(e.name || "endpoint")}</b>${e.version ? ` <small>v${esc(e.version)}</small>` : ""}<br><code>${link(e.endpoint, e.endpoint)}</code></li>`).join("")}</ul>`
    : `<p class="muted">No endpoints listed.</p>`;
  const trust = g.supportedTrust?.length ? `<ul class="chips">${g.supportedTrust.map((t) => `<li>${esc(t)}</li>`).join("")}</ul>` : `<p class="muted">No supported trust model listed.</p>`;
  let rep = "";
  if (r.feedback) {
    const f = r.feedback;
    rep = f.count === 0
      ? `<p class="muted">No feedback yet for this agent.</p>`
      : `<p class="score"><span class="big">${esc(f.average)}</span> average over <b>${esc(f.count)}</b> feedback</p>
<table><thead><tr><th>Client</th><th>Score</th><th>Tags</th></tr></thead><tbody>${f.items.map((i) => `<tr><td><code title="${esc(i.client)}">${esc(short(i.client))}</code></td><td>${esc(i.score)}</td><td>${esc(i.tags.join(", "))}</td></tr>`).join("")}</tbody></table>`;
    rep = `<section class="card"><h3>Reputation</h3>${rep}</section>`;
  }
  const uri = r.tokenURI.startsWith("data:") ? `data: URI (${r.tokenURI.length} characters)` : r.tokenURI;
  return `<section class="card agent">
${img ? `<img class="avatar" src="${esc(img)}" alt="" width="96" height="96">` : ""}
<h2>${esc(g.name || "Unnamed agent")} <small>#${esc(r.agentId)}</small></h2>
<p>${esc(g.description || "No description.")}</p>
<dl><dt>Owner</dt><dd><code>${owner}</code></dd><dt>tokenURI</dt><dd><code>${link(r.tokenURI, uri)}</code></dd></dl>
</section>
<section class="card"><h3>Endpoints</h3>${eps}</section>
<section class="card"><h3>Supported trust</h3>${trust}</section>
${rep}`;
}
