  const rpc = async (m, p) => {
    const k = JSON.stringify([m, p]);
    try { const r = await live(m, p); rec.rpc[k] = { result: r }; return r; }
    catch (e) { rec.rpc[k] = { error: { code: e.code, message: e.message } }; throw e; }
  };
  const fj = async (u) => {
    try { const j = await fetchJson(u); rec.files[u] = { json: j }; return j; }
    catch (e) { rec.files[u] = { error: e.message }; throw e; }
  };
  const r = await loadAgent({ agentId, network, reputationRegistry: REGISTRIES[network].reputation, rpc, fetchJson: fj });
  rec.expected = { status: r.status, owner: r.owner, tokenURI: r.tokenURI, name: r.registration?.name ?? null, count: r.feedback?.count ?? null, average: r.feedback?.average ?? null };
  console.log(network, agentId, JSON.stringify(rec.expected).slice(0, 200), r.error ?? "");
  if (!check) writeFileSync(new URL(`../test/fixtures/${network}-${agentId}.json`, import.meta.url), JSON.stringify(rec, null, 1) + "\n");
}
