import { readFileSync } from "node:fs";
export const fixture = (name) => JSON.parse(readFileSync(new URL(`./fixtures/${name}.json`, import.meta.url), "utf8"));
// Replays a recorded fixture: every RPC call and file fetch must have been recorded, so the tests run offline.
export function replay(fx) {
  const calls = { rpc: [], files: [] };
  const rpc = async (m, p) => {
    calls.rpc.push([m, p]);
    const hit = fx.rpc[JSON.stringify([m, p])];
    if (!hit) throw new Error("unrecorded rpc call " + JSON.stringify([m, p]).slice(0, 120));
    if (hit.error) throw Object.assign(new Error(hit.error.message), { code: hit.error.code });
    return hit.result;
  };
  const fetchJson = async (u) => {
    calls.files.push(u);
    const hit = fx.files[u];
    if (!hit) throw new Error("unrecorded file " + u);
    if (hit.error) throw new Error(hit.error);
    return hit.json;
  };
  return { rpc, fetchJson, calls };
}
