# aiax-validate

Validate and score any site's AIAX manifest and its sections against the AIAX 0.1 schemas (`schemas/manifest.schema.json` and `schemas/section.schema.json`, vendored from github.com/Godman-s/aiax).

```
npx aiax-validate <url> [--json] [--fixtures <dir>]
```

Exit code 0 when the site is valid, 1 when it is not, 2 on a usage error.

## How it works

1. The manifest is looked for at `/.well-known/aiax.json`, then `/aiax/manifest.json`, on the site origin.
2. The manifest is validated against the manifest schema (ajv, draft 2020-12, all errors). Duplicate entry point ids are errors too.
3. Every entry point `url` is resolved against the manifest URL and fetched. Each section is validated against the section schema, and its `section_id` must equal the entry point `id`.
4. Every problem becomes one `{url, path, message}`: `path` is a JSON pointer into the document, `message` names the field in plain words, for example `missing required field 'updated_at'` or `field 'pricing.model' must be one of "per_call", ... got "per_request"`. Branches of a `oneOf` are summarised in one message.

Errors: a missing manifest, a manifest or section that cannot be fetched or is not JSON, any schema violation, a section_id that differs from its entry point id, a repeated entry point id.

Warnings (they do not make a site invalid): the manifest above its 300 token target, a section above its 1,000 token target, an `est_tokens` off by more than 3 times from the measured size. Sizes are measured on the compact JSON (length / 4).

Score: 100 with no error and no warning, minus 20 per error and 2 per warning, floor 0; 0 when no usable manifest exists.

## API

```js
import { validateSite, fixtureFetch } from 'aiax-validate';
const report = await validateSite('https://lax.kognai.ai', { fetch }); // fetch is optional
// {url, manifest_url, ok, score, errors: [{url, path, message}], warnings: [...], sections: [{id, url, ok, errors}]}
```

`--fixtures <dir>` (or `fixtureFetch(dir)`) answers every fetch from `dir` + the URL path, a missing file is a 404, and nothing outside `dir` is ever read. The tool then runs offline.

## Fixtures

- `fixtures/lax`, `fixtures/kognai`: recorded from lax.kognai.ai and www.kognai.ai on 2026-10-24 (both valid, score 98).
- `fixtures/broken/*`: manifest-missing-field, manifest-wrong-type, manifest-extra-field, manifest-bad-entry-point-id, manifest-four-problems, manifest-missing, manifest-not-json, manifest-fallback-path (valid, manifest at /aiax/manifest.json), section-missing-field, section-bad-pricing, section-id-mismatch, section-missing, section-not-json.

## Tests

`npm test` runs 24 node:test cases named A1 to A5, without network. `AIAX_LIVE=1 npm test` also checks the two live sites.

Built by an autonomous AI agent run under the responsibility of its human operator.


`src/validate.js`:

```js
// AIAX 0.1 site validator: fetch the manifest and every section, validate, score, explain.
import { readFileSync } from 'node:fs';
import Ajv2020 from 'ajv/dist/2020.js';
import addFormats from 'ajv-formats';

const load = (name) => JSON.parse(readFileSync(new URL(`../schemas/${name}.schema.json`, import.meta.url), 'utf8'));
export const manifestSchema = load('manifest');
export const sectionSchema = load('section');

const ajv = new Ajv2020({ allErrors: true, strict: false });
addFormats(ajv);
const checkManifest = ajv.compile(manifestSchema);
const checkSection = ajv.compile(sectionSchema);

export const MANIFEST_PATHS = ['/.well-known/aiax.json', '/aiax/manifest.json'];
const ID_PATTERN = new RegExp(manifestSchema.properties.entry_points.items.properties.id.pattern);
export const ERROR_COST = 20;
export const WARNING_COST = 2;
// Target sizes named in the schema descriptions (Tier 0: 100 to 300 tokens, Tier 1: 200 to 1,000 tokens).
export const MANIFEST_TOKEN_TARGET = 300;
export const SECTION_TOKEN_TARGET = 1000;

const ONE_OF_HINTS = {
  inputs: 'must be an inline JSON Schema object or a prose string of at most 400 characters',
  outputs: 'must be an inline JSON Schema object or a prose string of at most 400 characters',
};

const escapeToken = (s) => String(s).replace(/~/g, '~0').replace(/\//g, '~1');
const unescapeToken = (s) => s.replace(/~1/g, '/').replace(/~0/g, '~');

/** JSON pointer -> readable field name: /entry_points/2/id -> entry_points[2].id */
export function fieldName(pointer) {
  if (!pointer) return 'the document';
  let out = '';
  for (const raw of pointer.split('/').slice(1)) {
    const seg = unescapeToken(raw);
    out += /^\d+$/.test(seg) ? `[${seg}]` : (out ? '.' : '') + seg;
  }
  return out;
}

const typeOf = (v) => (v === null ? 'null' : Array.isArray(v) ? 'array' : Number.isInteger(v) ? 'integer' : typeof v);
const show = (v) => JSON.stringify(v);

function valueAt(doc, pointer) {
  let cur = doc;
  for (const raw of pointer.split('/').slice(1)) {
    if (cur == null || typeof cur !== 'object') return undefined;
    cur = cur[unescapeToken(raw)];
  }
  return cur;
}

/** Turn ajv errors into {path, message} items, one per problem, in plain words. */
export function explain(errors, doc) {
  const oneOfPaths = new Set(errors.filter((e) => e.keyword === 'oneOf').map((e) => e.schemaPath));
  const out = [];
  const seen = new Set();
  for (const e of errors) {
    // Branch failures under a oneOf are summarised by the oneOf error itself.
    if ([...oneOfPaths].some((p) => e.schemaPath.startsWith(p + '/'))) continue;
    let path = e.instancePath;
    let message;
    const value = valueAt(doc, path);
    const name = fieldName(path);
    switch (e.keyword) {
      case 'required':
        path += '/' + escapeToken(e.params.missingProperty);
        message = `missing required field '${fieldName(path)}'`;
        break;
      case 'additionalProperties':
        path += '/' + escapeToken(e.params.additionalProperty);
        message = `unknown field '${fieldName(path)}' is not allowed`;
        break;
      case 'type': {
        const want = [].concat(e.params.type).join(' or ');
        message = path
          ? `field '${name}' must be ${want}, got ${typeOf(value)}`
          : `the document must be a JSON ${want}, got ${typeOf(value)}`;
        break;
      }
      case 'enum':
        message = `field '${name}' must be one of ${e.params.allowedValues.map(show).join(', ')}, got ${show(value)}`;
        break;
      case 'pattern':
        message = `field '${name}' has the wrong form: ${show(value)} does not match ${e.params.pattern}`;
        break;
      case 'maxLength':
        message = `field '${name}' is too long: ${value.length} characters, at most ${e.params.limit} allowed`;
        break;
      case 'minItems':
        message = `field '${name}' must have at least ${e.params.limit} item(s), it has ${value.length}`;
        break;
      case 'maxItems':
        message = `field '${name}' must have at most ${e.params.limit} item(s), it has ${value.length}`;
        break;
      case 'minimum':
      case 'maximum':
        message = `field '${name}' is out of range: ${show(value)}, it must be ${e.params.comparison} ${e.params.limit}`;
        break;
      case 'format':
        message = `field '${name}' must be a valid ${e.params.format}, got ${show(value)}`;
        break;
      case 'oneOf':
        message = `field '${name}' ${ONE_OF_HINTS[path.split('/').pop()] ?? 'matches none of the allowed forms'}`;
        break;
      default:
        message = `field '${name}' ${e.message}`;
    }
    const key = path + '\n' + message;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ path, message });
  }
  return out;
}

// Token size is measured on the compact JSON, so indentation does not change it.
const estTokens = (doc) => Math.ceil(JSON.stringify(doc).length / 4);

async function fetchJson(fetchFn, url) {
  let res;
  try {
    res = await fetchFn(url);
  } catch (err) {
    return { fail: `could not be fetched (${err?.message || 'network error'})` };
  }
  if (!res.ok) return { status: res.status, fail: `could not be fetched (HTTP ${res.status})` };
  const text = await res.text();
  try {
    return { text, doc: JSON.parse(text) };
  } catch {
    return { text, fail: 'is not valid JSON' };
  }
}

export function score(errors, warnings) {
  return Math.max(0, 100 - ERROR_COST * errors - WARNING_COST * warnings);
}

/**
 * Validate a site's AIAX manifest and its sections.
 * @param {string} url site URL (scheme optional, https assumed)
 * @param {{fetch?: typeof fetch}} [options]
 */
export async function validateSite(url, options = {}) {
  const fetchFn = options.fetch ?? globalThis.fetch;
  const site = new URL(/^[a-z][a-z0-9+.-]*:\/\//i.test(url) ? url : `https://${url}`);
  const errors = [];
  const warnings = [];
  const sections = [];
  // fatal: no usable manifest at all, so nothing of the site can be scored.
  const report = (manifest_url, fatal = false) => ({
    url: site.href,
    manifest_url,
    ok: errors.length === 0,
    score: fatal ? 0 : score(errors.length, warnings.length),
    errors,
    warnings,
    sections,
  });

  // 1. Find the manifest: /.well-known/aiax.json, then /aiax/manifest.json.
  let manifestUrl = null;
  let got = null;
  const misses = [];
  for (const p of MANIFEST_PATHS) {
    const candidate = new URL(p, site.origin).href;
    const r = await fetchJson(fetchFn, candidate);
    if (r.status !== undefined || r.text === undefined) {
      misses.push(`${p} ${r.fail}`);
      continue;
    }
    manifestUrl = candidate;
    got = r;
    break;
  }
  if (!got) {
    errors.push({ url: site.href, path: '', message: `no AIAX manifest found: ${misses.join('; ')}` });
    return report(null, true);
  }
  if (got.fail) {
    errors.push({ url: manifestUrl, path: '', message: `the manifest ${got.fail}` });
    return report(manifestUrl, true);
  }

  // 2. The manifest against manifest.schema.json, plus the checks a schema cannot express.
  const manifest = got.doc;
  if (manifest === null || typeof manifest !== 'object' || Array.isArray(manifest)) {
    errors.push({ url: manifestUrl, path: '', message: `the manifest must be a JSON object, got ${typeOf(manifest)}` });
    return report(manifestUrl, true);
  }
  if (!checkManifest(manifest)) {
    for (const e of explain(checkManifest.errors, manifest)) errors.push({ url: manifestUrl, ...e });
  }
  if (estTokens(manifest) > MANIFEST_TOKEN_TARGET) {
    warnings.push({ url: manifestUrl, path: '', message: `the manifest is about ${estTokens(manifest)} tokens, above the ${MANIFEST_TOKEN_TARGET} token target` });
  }
  const entryPoints = Array.isArray(manifest.entry_points) ? manifest.entry_points : [];
  const ids = new Map();
  entryPoints.forEach((ep, i) => {
    if (typeof ep?.id !== 'string') return;
    if (ids.has(ep.id)) {
      errors.push({ url: manifestUrl, path: `/entry_points/${i}/id`, message: `field 'entry_points[${i}].id' repeats the id ${show(ep.id)} already used by entry_points[${ids.get(ep.id)}]` });
    } else ids.set(ep.id, i);
  });

  // 3. Every entry point's section, resolved against the manifest URL.
  for (const [i, ep] of entryPoints.entries()) {
    if (typeof ep?.url !== 'string') continue;
    const id = typeof ep.id === 'string' ? ep.id : null;
    // An id already reported as malformed is not compared again with the section_id.
    const idUsable = id !== null && ID_PATTERN.test(id);
    const sec = { id, url: null, ok: false, errors: [] };
    sections.push(sec);
    const add = (path, message) => {
      const e = { url: sec.url ?? manifestUrl, path, message };
      sec.errors.push(e);
      errors.push(e);
    };
    try {
      sec.url = new URL(ep.url, manifestUrl).href;
    } catch {
      add(`/entry_points/${i}/url`, `field 'entry_points[${i}].url' is not a usable URL: ${show(ep.url)}`);
      continue;
    }
    const r = await fetchJson(fetchFn, sec.url);
    if (r.fail) {
      add('', `section ${show(id ?? ep.url)} ${r.fail}`);
      continue;
    }
    const doc = r.doc;
    if (!checkSection(doc)) for (const e of explain(checkSection.errors, doc)) add(e.path, e.message);
    if (idUsable && doc && typeof doc === 'object' && typeof doc.section_id === 'string' && doc.section_id !== id) {
      add('/section_id', `field 'section_id' is ${show(doc.section_id)} but the manifest entry point id is ${show(id)}`);
    }
    const measured = estTokens(doc);
    if (measured > SECTION_TOKEN_TARGET) {
      warnings.push({ url: sec.url, path: '', message: `section ${show(id)} is about ${measured} tokens, above the ${SECTION_TOKEN_TARGET} token target` });
    }
    if (Number.isInteger(ep.est_tokens) && (measured > 3 * ep.est_tokens || ep.est_tokens > 3 * measured)) {
      warnings.push({ url: manifestUrl, path: `/entry_points/${i}/est_tokens`, message: `field 'entry_points[${i}].est_tokens' says ${ep.est_tokens} but the section measures about ${measured} tokens` });
    }
    sec.ok = sec.errors.length === 0;
  }
  return report(manifestUrl);
}
