// A fetch that answers every URL from a file under dir (the URL path), 404 when the file is missing.
import { readFile, stat } from 'node:fs/promises';
import { resolve, sep } from 'node:path';

export function fixtureFetch(dir) {
  const root = resolve(dir);
  return async (input) => {
    const { pathname } = new URL(String(input));
    const file = resolve(root, '.' + decodeURIComponent(pathname));
    if (file !== root && !file.startsWith(root + sep)) return new Response('not found', { status: 404 });
    try {
      if (!(await stat(file)).isFile()) return new Response('not found', { status: 404 });
      return new Response(await readFile(file), { status: 200, headers: { 'content-type': 'application/json' } });
    } catch {
      return new Response('not found', { status: 404 });
    }
  };
}
