// CLI logic, kept apart from the bin so tests can drive it with their own streams.
import { statSync } from 'node:fs';
import { validateSite } from './validate.js';
import { fixtureFetch } from './fixtures.js';

export const USAGE = 'usage: aiax-validate <url> [--json] [--fixtures <dir>]';

/** @returns {Promise<0|1|2>} exit code */
export async function run(argv, { stdout = process.stdout, stderr = process.stderr, fetch } = {}) {
  let json = false;
  let fixtures = null;
  const urls = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--json') json = true;
    else if (a === '--fixtures') {
      fixtures = argv[++i];
      if (!fixtures) return usage(stderr, '--fixtures needs a directory');
    } else if (a === '-h' || a === '--help') {
      stdout.write(USAGE + '\n');
      return 0;
    } else if (a.startsWith('-')) return usage(stderr, `unknown option ${a}`);
    else urls.push(a);
  }
  if (urls.length !== 1) return usage(stderr, urls.length ? 'give exactly one url' : 'missing url');
  if (fixtures !== null) {
    let isDir = false;
    try { isDir = statSync(fixtures).isDirectory(); } catch {}
    if (!isDir) return usage(stderr, `fixtures directory not found: ${fixtures}`);
  }
  let rep;
  try {
    rep = await validateSite(urls[0], { fetch: fixtures !== null ? fixtureFetch(fixtures) : fetch });
  } catch (err) {
    if (err instanceof TypeError && /Invalid URL/i.test(String(err.message))) return usage(stderr, `not a valid url: ${urls[0]}`);
    throw err;
  }
  if (json) stdout.write(JSON.stringify(rep, null, 2) + '\n');
  else {
    for (const e of rep.errors) stdout.write(`error ${e.url} ${e.path || '/'}: ${e.message}\n`);
    for (const w of rep.warnings) stdout.write(`warning ${w.url} ${w.path || '/'}: ${w.message}\n`);
    stdout.write(`${rep.ok ? 'valid' : 'invalid'}: score ${rep.score}/100, ${rep.errors.length} error(s), ${rep.warnings.length} warning(s), ${rep.sections.length} section(s)\n`);
  }
  return rep.ok ? 0 : 1;
}

function usage(stderr, why) {
  stderr.write(`aiax-validate: ${why}\n${USAGE}\n`);
  return 2;
}
