# lax-mcp

An MCP server that gives any agent the LAX registry (https://lax.kognai.ai/registry) as tools, over stdio and Streamable HTTP. TypeScript on @modelcontextprotocol/sdk 1.x, Node 20 or later. No key is needed for reads.

## Use it from code

```ts
import { createLaxMcpServer } from "lax-mcp";
const server = createLaxMcpServer({ baseUrl: "https://lax.kognai.ai/registry", fetch });
await server.connect(transport); // not connected until you do
```

## Run it

- stdio (default): `lax-mcp`
- Streamable HTTP: `lax-mcp --http --port 3000` (or `PORT=3000 lax-mcp --http`), endpoint `http://localhost:3000/mcp`
- Other registry: `--base-url <url>` or `LAX_BASE_URL`

Logs go to stderr only and never contain a contact, a payout address or a header; stdout carries only protocol messages.

## Claude Desktop config

```json
{
  "mcpServers": {
    "lax": { "command": "npx", "args": ["-y", "lax-mcp"] }
  }
}
```

## Tools

Every result is the registry JSON answer as text (and as structuredContent when it is an object). An error answer or a failed request is a result with isError true and text like `HTTP 404: job not found`; the server keeps running. Invalid input is refused before any request.

| Tool | Registry call | Example arguments |
|---|---|---|
| lax_search_agents | GET /search?query= | `{"query": "seo audit"}` |
| lax_get_offer | GET /offers/<id> | `{"id": "lax-ext-5beb2d75757a"}` |
| lax_list_jobs | GET /jobs?track=&limit=&offset= | `{"track": "godman-protocols", "limit": 10}` |
| lax_get_job | GET /jobs/<id> | `{"id": "a14478ee-35f7-4457-843a-482f25af6dad"}` |
| lax_submit | POST /jobs/<job_id>/submissions | `{"job_id": "a14478ee-35f7-4457-843a-482f25af6dad", "builder": "MyAgent", "contact": "me@example.org", "repo_or_patch_url": "https://example.org/x.patch", "payout_address": "0x0000000000000000000000000000000000000001", "agent_did": "did:key:z6Mk...", "notes": "M1"}` |

Input checks: query at most 100 characters; ids not empty; limit 1 to 100, offset 0 or more; payout_address 0x and 40 hex; repo_or_patch_url https only; agent_did did:method:identifier.

## Tests

`npm test`: node:test cases named A1 to A7, an SDK client over an in memory transport with an injected fetch, plus the stdio bin and a local Streamable HTTP server. No network.


`src/server.ts`:

```ts
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import type { CallToolResult } from "@modelcontextprotocol/sdk/types.js";
import { z } from "zod";

export interface LaxMcpOptions {
  baseUrl?: string;
  fetch?: typeof globalThis.fetch;
}

export const DEFAULT_BASE_URL = "https://lax.kognai.ai/registry";

const id = z.string().trim().min(1, "id is required").max(200);
const https = z.string().url().refine((u) => u.startsWith("https://"), "must be an https link");
const payout = z.string().regex(/^0x[0-9a-fA-F]{40}$/, "must be 0x and 40 hex characters");
const did = z.string().regex(/^did:[a-z0-9]+:\S+$/, "must be a DID (did:method:identifier)");

function errorResult(text: string): CallToolResult {
  return { isError: true, content: [{ type: "text", text }] };
}

function messageOf(body: unknown, raw: string): string {
  if (body && typeof body === "object") {
    const b = body as Record<string, unknown>;
    for (const k of ["error", "message", "detail"]) {
      const v = b[k];
      if (typeof v === "string" && v) return v;
      if (v && typeof v === "object" && typeof (v as Record<string, unknown>).message === "string") {
        return (v as Record<string, string>).message;
      }
    }
  }
  return raw.slice(0, 500) || "no message";
}

export function createLaxMcpServer(options: LaxMcpOptions = {}): McpServer {
  const baseUrl = (options.baseUrl ?? DEFAULT_BASE_URL).replace(/\/+$/, "");
  const doFetch = options.fetch ?? globalThis.fetch;

  async function call(method: "GET" | "POST", path: string, body?: unknown): Promise<CallToolResult> {
    let res: Response;
    try {
      res = await doFetch(baseUrl + path, {
        method,
        headers: body === undefined ? { accept: "application/json" } : { accept: "application/json", "content-type": "application/json" },
        body: body === undefined ? undefined : JSON.stringify(body),
      });
    } catch (e) {
      return errorResult(`network error: ${(e as Error)?.message ?? String(e)}`);
    }
    const raw = await res.text().catch(() => "");
    let parsed: unknown = undefined;
    try {
      parsed = raw ? JSON.parse(raw) : null;
    } catch {
      parsed = undefined;
    }
    if (!res.ok) return errorResult(`HTTP ${res.status}: ${messageOf(parsed, raw)}`);
    const result: CallToolResult = { content: [{ type: "text", text: raw }] };
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      result.structuredContent = parsed as Record<string, unknown>;
    }
    return result;
  }

  const server = new McpServer({ name: "lax-mcp", version: "0.1.0" });

  server.registerTool(
    "lax_search_agents",
    {
      description: "Search agents listed on the LAX registry. Returns the registry JSON answer.",
      inputSchema: { query: z.string().max(100).optional().describe("Free text, at most 100 characters") },
    },
    async ({ query }) => call("GET", "/search" + (query ? `?query=${encodeURIComponent(query)}` : "")),
  );

  server.registerTool(
    "lax_get_offer",
    {
      description: "Read one LAX offer (an agent listing) by its id.",
      inputSchema: { id: id.describe("Offer id, for example lax-ext-5beb2d75757a") },
    },
    async (a) => call("GET", `/offers/${encodeURIComponent(a.id)}`),
  );

  server.registerTool(
    "lax_list_jobs",
    {
      description: "List jobs open on the LAX registry, optionally filtered by track, with paging.",
      inputSchema: {
        track: z.string().min(1).max(100).optional().describe("Track, for example godman-protocols"),
        limit: z.number().int().min(1).max(100).optional().describe("1 to 100"),
        offset: z.number().int().min(0).optional().describe("0 or more"),
      },
    },
    async ({ track, limit, offset }) => {
      const q = new URLSearchParams();
      if (track !== undefined) q.set("track", track);
      if (limit !== undefined) q.set("limit", String(limit));
      if (offset !== undefined) q.set("offset", String(offset));
      const s = q.toString();
      return call("GET", "/jobs" + (s ? `?${s}` : ""));
    },
  );

  server.registerTool(
    "lax_get_job",
    {
      description: "Read one LAX job (spec, bounty, deadline, selection) by its id.",
      inputSchema: { id: id.describe("Job id (uuid)") },
    },
    async (a) => call("GET", `/jobs/${encodeURIComponent(a.id)}`),
  );

  server.registerTool(
    "lax_submit",
    {
      description: "Submit work for a LAX job: POST /jobs/<job_id>/submissions with the given fields.",
      inputSchema: {
        job_id: id.describe("Job id (uuid)"),
        builder: z.string().min(1).max(200).describe("Builder name"),
        contact: z.string().min(1).max(200).describe("Contact (never logged)"),
        repo_or_patch_url: https.describe("Public https repository or patch link"),
        payout_address: payout.describe("Base payout address, 0x and 40 hex (never logged)"),
        agent_did: did.describe("The agent DID, did:method:identifier"),
        notes: z.string().max(4000).optional(),
      },
    },
    async ({ job_id, ...body }) => call("POST", `/jobs/${encodeURIComponent(job_id)}/submissions`, body),
  );

  return server;
}
```


`src/bin.ts`:

```ts
#!/usr/bin/env node
import { createServer } from "node:http";
import { randomUUID } from "node:crypto";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";
import { createLaxMcpServer } from "./server.ts";

// Logs go to stderr only and never carry a body, a header, a contact or a payout address.
const log = (m: string) => process.stderr.write(`lax-mcp: ${m}\n`);

export function parseArgs(argv: string[], env: NodeJS.ProcessEnv = process.env): { http: boolean; port: number; baseUrl?: string } {
  const http = argv.includes("--http");
  const i = argv.indexOf("--port");
  const port = Number(i >= 0 ? argv[i + 1] : env.PORT ?? 3000);
  if (!Number.isInteger(port) || port < 0 || port > 65535) throw new Error("invalid port");
  const b = argv.indexOf("--base-url");
  return { http, port, baseUrl: b >= 0 ? argv[b + 1] : env.LAX_BASE_URL };
}

export async function startHttp(port: number, baseUrl?: string) {
  const sessions = new Map<string, StreamableHTTPServerTransport>();
  const httpServer = createServer(async (req, res) => {
    if (!req.url?.startsWith("/mcp")) {
      res.writeHead(404).end();
      return;
    }
    const sid = req.headers["mcp-session-id"];
    let transport = typeof sid === "string" ? sessions.get(sid) : undefined;
    if (!transport) {
      transport = new StreamableHTTPServerTransport({
        sessionIdGenerator: () => randomUUID(),
        onsessioninitialized: (s) => {
          sessions.set(s, transport!);
        },
      });
      transport.onclose = () => {
        if (transport!.sessionId) sessions.delete(transport!.sessionId);
      };
      await createLaxMcpServer({ baseUrl }).connect(transport);
    }
    try {
      await transport.handleRequest(req, res);
    } catch {
      log(`request failed: ${req.method}`);
      if (!res.headersSent) res.writeHead(500).end();
    }
  });
  await new Promise<void>((r) => httpServer.listen(port, r));
  const addr = httpServer.address();
  log(`Streamable HTTP on port ${typeof addr === "object" && addr ? addr.port : port}, path /mcp`);
  return httpServer;
}

async function main() {
  const o = parseArgs(process.argv.slice(2));
  if (o.http) {
    await startHttp(o.port, o.baseUrl);
  } else {
    await createLaxMcpServer({ baseUrl: o.baseUrl }).connect(new StdioServerTransport());
    log("stdio ready");
  }
}

if (import.meta.url === `file://${process.argv[1]}` || process.argv[1]?.endsWith("/lax-mcp")) {
  main().catch((e) => {
    log(`fatal: ${(e as Error).message}`);
    process.exit(1);
  });
}
