```ts
import { test } from "node:test";
import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { InMemoryTransport } from "@modelcontextprotocol/sdk/inMemory.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";
import { createLaxMcpServer } from "../src/index.ts";
import { startHttp } from "../src/bin.ts";

type Call = { url: string; method: string; body?: string };

function fakeFetch(reply: (c: Call) => Response | Promise<Response>) {
  const calls: Call[] = [];
  const f = (async (url: string | URL, init?: RequestInit) => {
    const c = { url: String(url), method: init?.method ?? "GET", body: init?.body as string | undefined };
    calls.push(c);
    return reply(c);
  }) as typeof fetch;
  return { f, calls };
}

const json = (b: unknown, status = 200) => new Response(JSON.stringify(b), { status, headers: { "content-type": "application/json" } });

async function connect(f: typeof fetch, baseUrl = "https://reg.test/registry") {
  const server = createLaxMcpServer({ baseUrl, fetch: f });
  const [a, b] = InMemoryTransport.createLinkedPair();
  const client = new Client({ name: "t", version: "0" });
  await Promise.all([server.connect(a), client.connect(b)]);
  return client;
}

const text = (r: any) => r.content[0].text as string;
const SUB = {
  job_id: "96583e5f-0000",
  builder: "SurvieAgent",
  contact: "secret-contact@example.org",
  repo_or_patch_url: "https://example.org/patch.diff",
  payout_address: "0x786987916c7786Cf856dFC819C58DD97127381bA",
  agent_did: "did:key:z6Mkabc",
};

test("A1 tools/list returns the five tools with descriptions and input schemas", async () => {
  const c = await connect(fakeFetch(() => json({})).f);
  const { tools } = await c.listTools();
  assert.deepEqual(tools.map((t) => t.name).sort(), ["lax_get_job", "lax_get_offer", "lax_list_jobs", "lax_search_agents", "lax_submit"]);
  for (const t of tools) {
    assert.ok(t.description && t.description.length > 10);
    assert.equal(t.inputSchema.type, "object");
  }
  const submit = tools.find((t) => t.name === "lax_submit")!;
  assert.deepEqual([...(submit.inputSchema.required as string[])].sort(), ["agent_did", "builder", "contact", "job_id", "payout_address", "repo_or_patch_url"]);
});

test("A2 read tools call their routes and return the registry answer", async () => {
  const { f, calls } = fakeFetch((c) => json({ echo: c.url }));
  const c = await connect(f);
  const r1 = await c.callTool({ name: "lax_search_agents", arguments: { query: "seo audit" } });
  assert.equal(calls[0].url, "https://reg.test/registry/search?query=seo%20audit");
  assert.deepEqual(JSON.parse(text(r1)), { echo: calls[0].url });
  assert.deepEqual(r1.structuredContent, { echo: calls[0].url });
  await c.callTool({ name: "lax_get_offer", arguments: { id: "lax-ext-1" } });
  await c.callTool({ name: "lax_list_jobs", arguments: { track: "godman-protocols", limit: 5, offset: 10 } });
  await c.callTool({ name: "lax_list_jobs", arguments: {} });
  await c.callTool({ name: "lax_get_job", arguments: { id: "a/b" } });
  assert.deepEqual(calls.slice(1).map((x) => x.url), [
    "https://reg.test/registry/offers/lax-ext-1",
    "https://reg.test/registry/jobs?track=godman-protocols&limit=5&offset=10",
    "https://reg.test/registry/jobs",
    "https://reg.test/registry/jobs/a%2Fb",
  ]);
  assert.ok(calls.every((x) => x.method === "GET"));
});

test("A2 lax_submit POSTs the JSON body without job_id", async () => {
  const { f, calls } = fakeFetch(() => json({ submission: { id: "s1" } }, 201));
  const c = await connect(f);
  const r = await c.callTool({ name: "lax_submit", arguments: { ...SUB, notes: "M1" } });
  assert.equal(r.isError, undefined);
  assert.equal(calls[0].method, "POST");
  assert.equal(calls[0].url, "https://reg.test/registry/jobs/96583e5f-0000/submissions");
  const { job_id, ...rest } = SUB;
  assert.deepEqual(JSON.parse(calls[0].body!), { ...rest, notes: "M1" });
  assert.deepEqual(JSON.parse(text(r)), { submission: { id: "s1" } });
});

test("A2 default baseUrl is the live registry", async () => {
  const { f, calls } = fakeFetch(() => json({ jobs: [] }));
  const server = createLaxMcpServer({ fetch: f });
  const [a, b] = InMemoryTransport.createLinkedPair();
  const c = new Client({ name: "t", version: "0" });
  await Promise.all([server.connect(a), c.connect(b)]);
  await c.callTool({ name: "lax_list_jobs", arguments: { limit: 1 } });
  assert.equal(calls[0].url, "https://lax.kognai.ai/registry/jobs?limit=1");
});

test("A3 4xx, 5xx and network failures give isError with status and message, and the server keeps working", async () => {
  let n = 0;
  const { f } = fakeFetch(() => {
    n++;
    if (n === 1) return json({ error: "job not found" }, 404);
    if (n === 2) return new Response("upstream down", { status: 503 });
    if (n === 3) throw new TypeError("fetch failed");
    return json({ job: { id: "ok" } });
  });
  const c = await connect(f);
  const r1 = await c.callTool({ name: "lax_get_job", arguments: { id: "x" } });
  assert.equal(r1.isError, true);
  assert.match(text(r1), /404/);
  assert.match(text(r1), /job not found/);
  const r2 = await c.callTool({ name: "lax_get_job", arguments: { id: "x" } });
  assert.equal(r2.isError, true);
  assert.match(text(r2), /503.*upstream down/);
  const r3 = await c.callTool({ name: "lax_get_job", arguments: { id: "x" } });
  assert.equal(r3.isError, true);
  assert.match(text(r3), /network error: fetch failed/);
  const r4 = await c.callTool({ name: "lax_get_job", arguments: { id: "x" } });
  assert.equal(r4.isError, undefined);
  assert.deepEqual(JSON.parse(text(r4)), { job: { id: "ok" } });
});

test("A4 invalid input is refused without a request", async () => {
  const { f, calls } = fakeFetch(() => json({}));
  const c = await connect(f);
  const bad: [string, Record<string, unknown>][] = [
    ["lax_get_job", {}],
    ["lax_get_job", { id: "" }],
    ["lax_get_offer", {}],
    ["lax_search_agents", { query: "x".repeat(101) }],
    ["lax_list_jobs", { limit: 0 }],
    ["lax_list_jobs", { limit: 101 }],
    ["lax_submit", { ...SUB, payout_address: "0x123" }],
    ["lax_submit", { ...SUB, payout_address: "786987916c7786Cf856dFC819C58DD97127381bA00" }],
    ["lax_submit", { ...SUB, repo_or_patch_url: "http://example.org/x" }],
    ["lax_submit", { ...SUB, repo_or_patch_url: "not a link" }],
    ["lax_submit", { ...SUB, agent_did: "z6Mk" }],
    ["lax_submit", { ...SUB, job_id: undefined }],
  ];
  for (const [name, args] of bad) {
    let refused = false;
    try {
      const r = await c.callTool({ name, arguments: args });
      refused = r.isError === true;
    } catch {
      refused = true;
    }
    assert.ok(refused, `${name} ${JSON.stringify(args)} should be refused`);
  }
  assert.equal(calls.length, 0);
});

function runBin(args: string[], input: string, env: Record<string, string> = {}): Promise<{ out: string; err: string }> {
  return new Promise((resolve) => {
    const p = spawn(process.execPath, ["--import", "tsx", "src/bin.ts", ...args], { env: { PATH: process.env.PATH!, ...env } });
    let out = "", err = "";
    p.stdout.on("data", (d) => (out += d));
    p.stderr.on("data", (d) => (err += d));
    p.stdin.write(input);
    setTimeout(() => p.kill(), 2500);
    p.on("close", () => resolve({ out, err }));
  });
}

test("A5 stdio: only protocol messages on stdout, no contact, payout or header in logs", async () => {
  const msgs = [
    { jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "t", version: "0" } } },
    { jsonrpc: "2.0", method: "notifications/initialized" },
    { jsonrpc: "2.0", id: 2, method: "tools/list" },
    // unreachable base url so the submit fails without leaving the machine
    { jsonrpc: "2.0", id: 3, method: "tools/call", params: { name: "lax_submit", arguments: SUB } },
  ];
  const { out, err } = await runBin([], msgs.map((m) => JSON.stringify(m)).join("\n") + "\n", { LAX_BASE_URL: "http://127.0.0.1:9/registry" });
  const lines = out.trim().split("\n");
  assert.ok(lines.length >= 3);
  for (const l of lines) assert.equal(JSON.parse(l).jsonrpc, "2.0");
  assert.equal(JSON.parse(lines[1]).result.tools.length, 5);
  assert.match(err, /stdio ready/);
  for (const secret of [SUB.contact, SUB.payout_address, "content-type", "authorization"]) assert.ok(!err.toLowerCase().includes(secret.toLowerCase()), secret);
});

test("A6 Streamable HTTP serves the same tools", async () => {
  const srv = await startHttp(0, "http://127.0.0.1:9/registry");
  const port = (srv.address() as { port: number }).port;
  const c = new Client({ name: "t", version: "0" });
  await c.connect(new StreamableHTTPClientTransport(new URL(`http://127.0.0.1:${port}/mcp`)));
  const { tools } = await c.listTools();
  assert.equal(tools.length, 5);
  const r = await c.callTool({ name: "lax_get_job", arguments: { id: "x" } });
  assert.equal(r.isError, true);
  await c.close();
  srv.close();
  srv.closeAllConnections();
});

test("A6 package has a bin and the stdio default", async () => {
  const pkg = JSON.parse(await (await import("node:fs/promises")).readFile("package.json", "utf8"));
  assert.ok(pkg.bin["lax-mcp"]);
  const { parseArgs } = await import("../src/bin.ts");
