  assert.equal(parseArgs(["--http", "--port", "8080"], {}).port, 8080);
  assert.equal(parseArgs(["--http"], { PORT: "9090" }).port, 9090);
});

test("A7 README has the Claude Desktop config and an example for every tool", async () => {
  const md = await (await import("node:fs/promises")).readFile("README.md", "utf8");
  assert.match(md, /"mcpServers"/);
  for (const t of ["lax_search_agents", "lax_get_offer", "lax_list_jobs", "lax_get_job", "lax_submit"]) assert.ok(md.includes(t), t);
