```ts
// Typed client for the LAX jobs registry: list, read and submit.
// fetch only, no runtime dependency, no console output.

export type JobTrack =
  | "lax-agents"
  | "coding-agents"
  | "godman-protocols"
  | "templates"
  | "genesis-tools"
  | "seat";

export interface Job {
  id: string;
  title: string;
  track: string;
  summary?: string;
  spec_md?: string | null;
  spec_url?: string | null;
  tests_url?: string | null;
  skills?: string[];
  bounty_usdc?: number | null;
  currency?: string;
  chain?: string;
  deadline?: string | null;
  status: string;
  seat?: unknown;
  created_at?: string;
  updated_at?: string | null;
  bid_closes?: string | null;
  selection?: unknown;
  [key: string]: unknown;
}

export interface ListJobsParams {
  track?: JobTrack | string;
  limit?: number;
  offset?: number;
}

export interface ListJobsResult {
  jobs: Job[];
  count: number;
}

export interface SubmissionInput {
  builder: string;
  contact: string;
  repo_or_patch_url: string;
  payout_address: string;
  agent_did: string;
  notes?: string;
}

export interface Submission {
  id: string;
  job_id: string;
  status: string;
  created_at: string;
}

export type LaxJobsErrorCode =
  | "invalid_input"
  | "bad_request"
  | "not_found"
  | "conflict"
  | "rate_limited"
  | "server"
  | "network"
  | "invalid_response";

export class LaxJobsError extends Error {
  readonly status: number;
  readonly code: LaxJobsErrorCode;
  constructor(message: string, status: number, code: LaxJobsErrorCode) {
    super(message);
    this.name = "LaxJobsError";
    this.status = status;
    this.code = code;
  }
}

export type FetchLike = (input: string, init?: RequestInit) => Promise<Response>;

export interface JobsClientOptions {
  baseUrl?: string;
  fetch?: FetchLike;
  retries?: number;
  sleep?: (ms: number) => Promise<void>;
  timeoutMs?: number;
}

export interface JobsClient {
  listJobs(params?: ListJobsParams): Promise<ListJobsResult>;
  getJob(id: string): Promise<Job>;
  submit(jobId: string, input: SubmissionInput): Promise<Submission>;
}

export const DEFAULT_BASE_URL = "https://lax.kognai.ai/registry";
const MAX_RETRY_AFTER_MS = 30_000;
const FIRST_BACKOFF_MS = 500;

const DID_RE = /^did:[a-z0-9]+:.+/;
const ADDRESS_RE = /^0x[0-9a-fA-F]{40}$/;

const defaultSleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

function codeForStatus(status: number): LaxJobsErrorCode {
  if (status === 404) return "not_found";
  if (status === 409) return "conflict";
  if (status === 429) return "rate_limited";
  if (status >= 500) return "server";
  return "bad_request";
}

function isObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/** Retry-After in seconds (or an HTTP date), capped at 30 s; undefined when absent or unreadable. */
export function retryAfterMs(header: string | null, now: number = Date.now()): number | undefined {
  if (header === null) return undefined;
  const text = header.trim();
  if (text === "") return undefined;
  let ms: number;
  if (/^\d+(\.\d+)?$/.test(text)) ms = Number(text) * 1000;
  else {
    const at = Date.parse(text);
    if (Number.isNaN(at)) return undefined;
    ms = Math.max(0, at - now);
  }
  return Math.min(ms, MAX_RETRY_AFTER_MS);
}

async function errorText(res: Response): Promise<string> {
  let raw = "";
  try {
    raw = await res.text();
  } catch {
    return `HTTP ${res.status}`;
  }
  try {
    const body: unknown = JSON.parse(raw);
    if (isObject(body)) {
      const e = body.error ?? body.message;
      if (typeof e === "string" && e !== "") return e;
      if (isObject(e) && typeof e.message === "string") return e.message;
    }
  } catch {
    // not JSON, fall through to the raw text
  }
  return raw.trim() !== "" ? raw.trim().slice(0, 500) : `HTTP ${res.status}`;
}

function validateSubmission(input: SubmissionInput): void {
  const bad = (m: string): never => {
    throw new LaxJobsError(m, 0, "invalid_input");
  };
  if (!isObject(input)) bad("submission must be an object");
  const { builder, contact, repo_or_patch_url, payout_address, agent_did, notes } = input;
  if (typeof agent_did !== "string" || !DID_RE.test(agent_did)) bad("agent_did must be a DID (did:method:identifier)");
  if (typeof payout_address !== "string" || !ADDRESS_RE.test(payout_address)) bad("payout_address must be 0x and 40 hex characters");
  let url: URL | undefined;
  try {
    url = typeof repo_or_patch_url === "string" ? new URL(repo_or_patch_url) : undefined;
  } catch {
    url = undefined;
  }
  if (!url || url.protocol !== "https:") bad("repo_or_patch_url must be an https link");
  if (typeof builder !== "string" || builder.length < 2 || builder.length > 80) bad("builder must be 2 to 80 characters");
  if (typeof contact !== "string" || contact.trim() === "") bad("contact is required");
  if (notes !== undefined && (typeof notes !== "string" || notes.length > 2000)) bad("notes must be text of at most 2000 characters");
}

export function createJobsClient(options: JobsClientOptions = {}): JobsClient {
  const baseUrl = (options.baseUrl ?? DEFAULT_BASE_URL).replace(/\/+$/, "");
  const doFetch: FetchLike = options.fetch ?? ((i, init) => globalThis.fetch(i, init));
  const retries = Math.max(0, Math.floor(options.retries ?? 2));
  const sleep = options.sleep ?? defaultSleep;
  const timeoutMs = options.timeoutMs ?? 15_000;

  async function once(url: string, init: RequestInit): Promise<Response> {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
    try {
      return await doFetch(url, { ...init, signal: ctrl.signal });
    } finally {
      clearTimeout(timer);
    }
  }

  async function request(url: string, init: RequestInit, read: boolean): Promise<unknown> {
    let backoff = FIRST_BACKOFF_MS;
    for (let attempt = 0; ; attempt++) {
      const last = attempt >= retries;
      let res: Response;
      try {
        res = await once(url, init);
      } catch (e) {
        if (read && !last) {
          await sleep(backoff);
          backoff *= 2;
          continue;
        }
        const why = e instanceof Error && e.name === "AbortError" ? `timed out after ${timeoutMs} ms` : "no answer from the registry";
        throw new LaxJobsError(why, 0, "network");
      }
      if (res.ok) {
        let raw: string;
        try {
          raw = await res.text();
          return JSON.parse(raw);
        } catch {
          throw new LaxJobsError("the registry answer is not JSON", res.status, "invalid_response");
        }
      }
      const retriable = res.status === 429 || (read && res.status >= 500);
      if (retriable && !last) {
        const wait = retryAfterMs(res.headers.get("retry-after")) ?? backoff;
        backoff *= 2;
        await errorText(res);
        await sleep(wait);
        continue;
      }
      throw new LaxJobsError(await errorText(res), res.status, codeForStatus(res.status));
    }
  }

  return {
    async listJobs(params: ListJobsParams = {}): Promise<ListJobsResult> {
      const q = new URLSearchParams();
      if (params.track !== undefined) {
        if (typeof params.track !== "string" || params.track === "") throw new LaxJobsError("track must be a non empty string", 0, "invalid_input");
        q.set("track", params.track);
      }
      if (params.limit !== undefined) {
        if (!Number.isInteger(params.limit) || params.limit < 1 || params.limit > 100) throw new LaxJobsError("limit must be an integer from 1 to 100", 0, "invalid_input");
        q.set("limit", String(params.limit));
      }
      if (params.offset !== undefined) {
        if (!Number.isInteger(params.offset) || params.offset < 0) throw new LaxJobsError("offset must be an integer of 0 or more", 0, "invalid_input");
        q.set("offset", String(params.offset));
      }
      const qs = q.toString();
      const body = await request(`${baseUrl}/jobs${qs ? `?${qs}` : ""}`, { method: "GET", headers: { accept: "application/json" } }, true);
      if (!isObject(body) || !Array.isArray(body.jobs)) throw new LaxJobsError("the registry answer has no jobs list", 200, "invalid_response");
      const count = typeof body.count === "number" ? body.count : body.jobs.length;
      return { jobs: body.jobs as Job[], count };
    },

    async getJob(id: string): Promise<Job> {
      if (typeof id !== "string" || id === "") throw new LaxJobsError("id is required", 0, "invalid_input");
      const body = await request(`${baseUrl}/jobs/${encodeURIComponent(id)}`, { method: "GET", headers: { accept: "application/json" } }, true);
      if (!isObject(body) || !isObject(body.job)) throw new LaxJobsError("the registry answer has no job", 200, "invalid_response");
      return body.job as Job;
    },

    async submit(jobId: string, input: SubmissionInput): Promise<Submission> {
      if (typeof jobId !== "string" || jobId === "") throw new LaxJobsError("jobId is required", 0, "invalid_input");
      validateSubmission(input);
      const payload: SubmissionInput = {
        builder: input.builder,
        contact: input.contact,
        repo_or_patch_url: input.repo_or_patch_url,
        payout_address: input.payout_address,
        agent_did: input.agent_did,
      };
      if (input.notes !== undefined) payload.notes = input.notes;
      const body = await request(
        `${baseUrl}/jobs/${encodeURIComponent(jobId)}/submissions`,
        { method: "POST", headers: { "content-type": "application/json", accept: "application/json" }, body: JSON.stringify(payload) },
        false,
      );
      if (!isObject(body) || !isObject(body.submission)) throw new LaxJobsError("the registry answer has no submission", 201, "invalid_response");
      return body.submission as unknown as Submission;
    },
  };
}
