import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { createJobsClient, LaxJobsError, retryAfterMs, type FetchLike } from "../src/index.ts";

type Answer = { status: number; body?: unknown; headers?: Record<string, string> } | "network" | "abort";
interface Call { url: string; init?: RequestInit }

function fake(answers: Answer[]) {
  const calls: Call[] = [];
  const sleeps: number[] = [];
  const fetch: FetchLike = async (url, init) => {
    calls.push({ url, init });
    const a = answers[Math.min(calls.length - 1, answers.length - 1)];
    if (a === "network") throw new TypeError("fetch failed");
    if (a === "abort") throw Object.assign(new Error("aborted"), { name: "AbortError" });
    const text = typeof a.body === "string" ? a.body : JSON.stringify(a.body ?? {});
    return new Response(a.status === 204 ? null : text, { status: a.status, headers: a.headers });
  };
  const sleep = async (ms: number) => { sleeps.push(ms); };
  const client = createJobsClient({ fetch, sleep, baseUrl: "https://reg.test/registry" });
  return { client, calls, sleeps };
}

const JOB = { id: "96583e5f-4a9b", title: "LAX jobs client", track: "godman-protocols", status: "open", bounty_usdc: 200 };
const SUB = { id: "s1", job_id: "96583e5f-4a9b", status: "received", created_at: "2026-10-24T03:00:00Z" };
const INPUT = {
  builder: "SurvieAgent",
  contact: "agent@example.org",
  repo_or_patch_url: "https://example.org/patch.diff",
  payout_address: "0x786987916c7786Cf856dFC819C58DD97127381bA",
  agent_did: "did:key:z6MkExample",
};

async function rejects(p: Promise<unknown>, status: number, code: string, message?: string) {
  await assert.rejects(p, (e: unknown) => {
    assert.ok(e instanceof LaxJobsError);
    assert.ok(e instanceof Error);
    assert.equal(e.name, "LaxJobsError");
    assert.equal(e.status, status);
    assert.equal(e.code, code);
    if (message !== undefined) assert.equal(e.message, message);
    return true;
  });
}

