```ts
// Drive the five chambers in order. Stop at the first refusal and say where.
import type { NonceStore } from "./chambers/identity.ts";
import type { AgentRecord, OutsideScore, Tier } from "./chambers/trust.ts";
import type { ChamberName, Chambers, IntentRequest, JobTerms, SoulHandshake } from "./interfaces.ts";

export interface AirlockInput {
  identity: { challenge: unknown; signature: unknown; ownerAddress: unknown };
  record: AgentRecord;
  outside?: OutsideScore | null;
  intent: IntentRequest;
  job: JobTerms;
  soul: SoulHandshake;
}
export type AirlockResult =
  | { admitted: true; passed: ChamberName[]; tier: Tier; token: string }
  | { admitted: false; passed: ChamberName[]; refusedAt: ChamberName; reason: string };

export async function runAirlock(ch: Chambers, input: AirlockInput, now: number, usedNonces?: NonceStore): Promise<AirlockResult> {
  const passed: ChamberName[] = [];
  const refuse = (at: ChamberName, reason: string): AirlockResult => ({ admitted: false, passed, refusedAt: at, reason });

  const id = await ch.identity.verify({ ...input.identity, now, usedNonces });
  if (!id.ok) return refuse("identity", id.reason);
  passed.push("identity");
  const did = (input.identity.challenge as { did: string }).did;

  let tier: Tier;
  try { tier = ch.trust.score(input.record, input.outside).tier; }
  catch (e) { return refuse("trust", "invalid_record: " + (e as Error).message); }
  passed.push("trust");

  const it = ch.intent.check(input.intent, input.job, tier, now);
  if (!it.ok) return refuse("intent", it.reason);
  passed.push("intent");

  const so = ch.soul.handshake(input.soul, did);
  if (!so.ok) return refuse("soul", so.reason);
  passed.push("soul");

  const token = ch.session.issue({ did, jobId: input.job.jobId, tier }, now);
  const v = ch.session.verify(token, now);
  if (!v.ok) return refuse("session", v.reason);
  passed.push("session");
  return { admitted: true, passed, tier, token };
}
