// Cerberus chamber 3: intent. Is the request what this job allows, now?
import type { Decision, IntentRequest, JobTerms } from "../interfaces.ts";
import { TIERS, type Tier } from "./trust.ts";

export const ALLOWED_ACTIONS = ["bid", "deliver"] as const;
export const ALLOWED_SCOPES = ["registry:read", "bid:write", "delivery:write"] as const;

export function checkIntent(req: IntentRequest, job: JobTerms, tier: Tier, now: number): Decision {
  if (req.jobId !== job.jobId) return { ok: false, reason: "job_mismatch" };
  if (!(ALLOWED_ACTIONS as readonly string[]).includes(req.action)) return { ok: false, reason: "action_not_allowed" };
  const bad = req.scopes.find((s) => !(ALLOWED_SCOPES as readonly string[]).includes(s));
  if (bad !== undefined) return { ok: false, reason: `scope_not_allowed:${bad}` };
  if (TIERS.indexOf(tier) < TIERS.indexOf(job.minTier)) return { ok: false, reason: "tier_too_low" };
  if (req.action === "bid") {
    if (now >= Date.parse(job.bidCloses)) return { ok: false, reason: "bids_closed" };
    if (!(req.priceUsdc > 0) || req.priceUsdc > job.ceilingUsdc) return { ok: false, reason: "price_over_ceiling" };
  }
  const by = Date.parse(req.deliveryBy);
  if (Number.isNaN(by) || by <= now || by > Date.parse(job.deadline)) return { ok: false, reason: "delivery_out_of_window" };
  return { ok: true, reason: "ok" };
}
