// Cerberus chamber 4: SOUL handshake. The agent shows its SOUL document, its
// declared hash must match, and it must accept the Five Laws by name.
import { createHash } from "node:crypto";
import type { Decision, SoulHandshake } from "../interfaces.ts";

export const FIVE_LAWS = ["solidarity", "learning", "no debt", "no harm", "transparency"] as const;

export function soulHandshake(h: SoulHandshake, expectedDid: string): Decision {
  if (h.did !== expectedDid) return { ok: false, reason: "did_mismatch" };
  if (typeof h.soulMd !== "string" || h.soulMd.trim().length === 0) return { ok: false, reason: "empty_soul" };
  const digest = createHash("sha256").update(h.soulMd, "utf8").digest("hex");
  if (digest !== String(h.soulSha256).toLowerCase()) return { ok: false, reason: "soul_hash_mismatch" };
  const accepted = new Set(h.lawsAccepted.map((l) => l.trim().toLowerCase()));
  const missing = FIVE_LAWS.filter((l) => !accepted.has(l));
  if (missing.length > 0) return { ok: false, reason: `laws_missing:${missing.join(",")}` };
  return { ok: true, reason: "ok" };
}
