`src/chambers/session.ts`:

```ts
// Cerberus chamber 5: session token. Compact HMAC SHA256 token,
// base64url(header).base64url(claims).base64url(mac), with expiry.
import { createHmac, timingSafeEqual } from "node:crypto";
import type { Decision, SessionClaims, SessionChamber } from "../interfaces.ts";

const HEADER = Buffer.from(JSON.stringify({ alg: "HS256", typ: "cerberus" })).toString("base64url");

export function sessionChamber(secret: Buffer, ttlMs = 15 * 60 * 1000, skewMs = 0): SessionChamber {
  if (secret.length < 32) throw new Error("secret must be at least 32 bytes");
  const mac = (s: string) => createHmac("sha256", secret).update(s).digest();
  return {
    issue(c, now) {
      const claims: SessionClaims = { did: c.did, jobId: c.jobId, tier: c.tier, iat: now, exp: now + ttlMs };
      const body = HEADER + "." + Buffer.from(JSON.stringify(claims)).toString("base64url");
      return body + "." + mac(body).toString("base64url");
    },
    verify(token, now): Decision & { claims?: SessionClaims } {
      if (typeof token !== "string") return { ok: false, reason: "malformed" };
      const parts = token.split(".");
      if (parts.length !== 3 || parts[0] !== HEADER) return { ok: false, reason: "malformed" };
      const want = mac(parts[0] + "." + parts[1]);
      const got = Buffer.from(parts[2], "base64url");
      if (got.length !== want.length || !timingSafeEqual(got, want)) return { ok: false, reason: "bad_signature" };
      let claims: SessionClaims;
      try { claims = JSON.parse(Buffer.from(parts[1], "base64url").toString("utf8")); }
      catch { return { ok: false, reason: "malformed" }; }
      if (!Number.isFinite(claims.exp) || !Number.isFinite(claims.iat)) return { ok: false, reason: "malformed" };
      if (now < claims.iat - skewMs) return { ok: false, reason: "not_yet_valid" };
      if (now >= claims.exp + skewMs) return { ok: false, reason: "expired" };
      return { ok: true, reason: "ok", claims };
    },
  };
}
