import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { createHmac } from "node:crypto";
import { runAirlock } from "../src/airlock.ts";
import { referenceChambers } from "../src/reference.ts";
import { sessionChamber } from "../src/chambers/session.ts";
import { CHAMBERS, type Chambers } from "../src/interfaces.ts";

const load = (n: string) => JSON.parse(readFileSync(new URL(`./fixtures/${n}`, import.meta.url), "utf8"));
const base = load("base.json");
const sigs = load("signatures.json");
const cases: Array<{ name: string; set: Record<string, unknown>; expect: Record<string, unknown> }> = load("cases.json");
const SECRET = Buffer.alloc(32, 7);

function apply(set: Record<string, unknown>) {
  const o = structuredClone(base);
  for (const [path, raw] of Object.entries(set)) {
    const v = raw === "$otherSigner" ? sigs.otherSigner : raw;
    const keys = path.split(".");
    let cur = o;
    for (const k of keys.slice(0, -1)) cur = cur[k];
    cur[keys.at(-1)!] = v;
  }
  return o;
}

for (const c of cases) {
  test(`fixture: ${c.name}`, async () => {
    const f = apply(c.set);
    const r = await runAirlock(referenceChambers(SECRET), f, f.now, new Set());
    const e = c.expect;
    if (e.admitted) {
      assert.equal(r.admitted, true, JSON.stringify(r));
    } else {
      assert.equal(r.admitted, false);
      if (r.admitted) return;
      assert.equal(r.refusedAt, e.refusedAt);
      if (e.reason) assert.equal(r.reason, e.reason);
      if (e.reasonStarts) assert.ok(r.reason.startsWith(e.reasonStarts as string), r.reason);
      // Chambers run in order: everything before the refusing chamber passed.
      assert.deepEqual(r.passed, CHAMBERS.slice(0, CHAMBERS.indexOf(r.refusedAt)));
    }
    if (e.passed !== undefined) assert.equal(r.passed.length, e.passed);
  });
}

