import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { canon, createWriter, emit, EventError, findAnomalies, readStream, reportSection, validate, verifyStream, type TenderEvent } from "../src/ksl.ts";

const tmp = () => join(mkdtempSync(join(tmpdir(), "ksl-")), "events.jsonl");
const D = "2026-10-24";
const t = (h: string) => `${D}T${h}:00Z`;

// A clean tender, every step in order.
const clean: TenderEvent[] = [
  { step: "listing", at: t("08:00"), agent_id: "a1" },
  { step: "airlock", at: t("08:01"), agent_id: "a1", decision: "admit" },
  { step: "bid", at: t("09:00"), job_id: "j1", agent_id: "a1", bid_id: "b1", amount_usdc: 40 },
  { step: "selection", at: t("10:00"), job_id: "j1", agent_id: "a1", bid_id: "b1" },
  { step: "award", at: t("10:05"), job_id: "j1", agent_id: "a1", bid_id: "b1" },
  { step: "delivery", at: t("12:00"), job_id: "j1", agent_id: "a1" },
  { step: "review", at: t("13:00"), job_id: "j1", agent_id: "a1", verdict: "accepted" },
  { step: "payment", at: t("14:00"), job_id: "j1", agent_id: "a1", amount_usdc: 40 },
];

test("emit appends one JSON line per event and chains hashes", () => {
  const p = tmp();
  const w = createWriter(p);
  const stored = clean.map((e) => w.emit(e));
  const lines = readFileSync(p, "utf8").trim().split("\n");
  assert.equal(lines.length, 8);
  assert.equal(stored[0].prev, "0".repeat(64));
  for (let i = 1; i < stored.length; i++) assert.equal(stored[i].prev, stored[i - 1].hash);
  assert.deepEqual(verifyStream(readStream(p)), { ok: true });
});

test("a new writer continues the chain of an existing stream", () => {
  const p = tmp();
  createWriter(p).emit(clean[0]);
  const second = emit(clean[1], p);
  assert.equal(second.seq, 1);
  assert.deepEqual(verifyStream(readStream(p)), { ok: true });
});

test("emit uses KSL_STREAM when no path is given", () => {
  const p = tmp();
  process.env.KSL_STREAM = p;
  emit(clean[0]);
  delete process.env.KSL_STREAM;
  assert.equal(readStream(p).length, 1);
});

test("editing, removing or reordering a past line is detected and the writer refuses to append", () => {
  const base = tmp();
  const w = createWriter(base);
  clean.slice(0, 3).forEach((e) => w.emit(e));
  const lines = readFileSync(base, "utf8").trim().split("\n");

  const edited = JSON.parse(lines[2]); edited.amount_usdc = 4000;
  const cases: [string[], string][] = [
    [[lines[0], lines[1], JSON.stringify(edited)], "hash mismatch"],
    [[lines[0], lines[2]], "sequence gap"],
    [[lines[1], lines[0]], "sequence gap"],
  ];
  for (const [ls, reason] of cases) {
    const p = tmp(); writeFileSync(p, ls.join("\n") + "\n");
    const v = verifyStream(readStream(p));
    assert.equal(v.ok, false); assert.equal((v as { reason: string }).reason, reason);
    assert.throws(() => createWriter(p), EventError);
  }
  // Same seq, rewritten prev: the chain itself is broken.
  const forged = JSON.parse(lines[1]); forged.prev = "f".repeat(64);
  const p = tmp(); writeFileSync(p, [lines[0], JSON.stringify(forged)].join("\n") + "\n");
  assert.equal((verifyStream(readStream(p)) as { reason: string }).reason, "broken chain");
});

test("validation refuses malformed events and writes nothing", () => {
  const p = tmp();
  const w = createWriter(p);
  const bad: unknown[] = [
    null,
    { step: "bribe", at: t("08:00"), agent_id: "a1" },
    { step: "listing", at: "yesterday", agent_id: "a1" },
    { step: "listing", at: "2026-13-45T99:99:99Z", agent_id: "a1" },
    { step: "listing", at: t("08:00") },
    { step: "delivery", at: t("08:00"), agent_id: "a1" },
    { step: "bid", at: t("08:00"), agent_id: "a1", job_id: "j1", amount_usdc: 5 },
    { step: "bid", at: t("08:00"), agent_id: "a1", job_id: "j1", bid_id: "b1", amount_usdc: -1 },
    { step: "payment", at: t("08:00"), agent_id: "a1", job_id: "j1", amount_usdc: Number.NaN },
    { step: "airlock", at: t("08:00"), agent_id: "a1", decision: "maybe" },
    { step: "review", at: t("08:00"), agent_id: "a1", job_id: "j1" },
  ];
  for (const e of bad) assert.throws(() => w.emit(e as TenderEvent), EventError);
  assert.equal(readStream(p).length, 0);
  assert.doesNotThrow(() => validate(clean[2]));
});

test("canonical JSON ignores key order and undefined fields", () => {
  assert.equal(canon({ b: 1, a: [true, null, "x"], c: undefined }), canon({ a: [true, null, "x"], b: 1 }));
});

test("a clean tender has no anomalies and every step counted once", () => {
  const md = reportSection(clean, D);
  for (const s of ["listing", "airlock", "bid", "selection", "award", "delivery", "review", "payment"]) assert.match(md, new RegExp(`\\| ${s} \\| 1 \\|`));
