test("a bid without an airlock decision is an anomaly", () => {
  const ev = [clean[0], clean[2]];
  const a = findAnomalies(ev, D);
  assert.deepEqual(a.map((x) => x.kind), ["bid without an airlock decision"]);
  assert.match(reportSection(ev, D), /### Anomalies \(1\)\n\n- 2026-10-24T09:00:00Z bid without an airlock decision: agent a1, job j1, bid b1/);
});

test("a bid from a refused agent is an anomaly of its own kind", () => {
  const ev: TenderEvent[] = [{ ...clean[1], decision: "refuse" }, clean[2]];
  assert.deepEqual(findAnomalies(ev, D).map((x) => x.kind), ["bid from an agent refused at the airlock"]);
  assert.match(reportSection(ev, D), /Airlock refusals: 1\./);
});

test("a payment without acceptance is an anomaly, also after a rejected review", () => {
  const noReview = clean.filter((e) => e.step !== "review");
