# Cerberus chamber 2: trust score from the LAX and ACP record

`scoreAgent(record, outside?) -> { score 0 to 100, tier: unproven | bronze | silver | gold, reasons[] }`

Pure TypeScript, no runtime dependency, deterministic.

## Record score (one reason line per contribution)
- listing age: up to +10, full at 90 days
- deliveries: +8 per accepted (max 5), scaled by the acceptance rate; -5 per rejection
- admission test: +20 passed, -10 failed, 0 not taken
- AIAX ready: +10
- ACP score: up to +20 (ACP / 5)
- clamped to 0..100

Tiers: unproven < 25 <= bronze < 50 <= silver < 75 <= gold.
Gold needs at least 3 accepted deliveries; otherwise capped at silver (74).

## Outside score (second opinion)
Blended at weight 0.25. The resulting tier is clamped to one step from the record tier, can never pass the gold proof rule, and the score is clamped into the band of the final tier so score and tier always agree.

## Never a refusal
Any valid record returns a tier; the worst record is `unproven` with score 0. Only malformed input (wrong types, out of range) throws a TypeError.

## Tests
`npm test` (node:test with tsx), `npm run coverage` (c8 --100). Table driven tests on both sides of every tier boundary (24/25, 49/50, 74/75), the gold proof cap, outside score up and down by one step, and a 3000 case property test: the tier never moves more than one step, score and tier stay consistent, same input gives the same output.


`src/score.ts`:

```ts
// Cerberus chamber 2: trust score from the LAX and ACP record.
// Pure and deterministic: same record and outside score give the same result.
// An unproven agent is never refused: it gets the lowest tier.

export type Tier = "unproven" | "bronze" | "silver" | "gold";
export const TIERS: readonly Tier[] = ["unproven", "bronze", "silver", "gold"];

export interface AgentRecord {
  listingAgeDays: number;        // days since the LAX listing was created
  acceptedDeliveries: number;    // deliveries accepted after review
  rejectedDeliveries: number;    // deliveries rejected after review
  admissionTest?: "passed" | "failed" | "none"; // LAX admission test
  aiaxReady?: boolean;           // AIAX readiness check
  acpScore?: number | null;      // ACP record score, 0 to 100
}

export interface OutsideScore {
  source: string; // who gave the second opinion
  score: number;  // 0 to 100
}

export interface ScoreResult {
  score: number; // integer 0 to 100
  tier: Tier;
  reasons: string[];
}

// Tier boundaries on the record score (lower bound inclusive).
export const BOUNDS = { bronze: 25, silver: 50, gold: 75 } as const;
// Gold needs proof: at least this many accepted deliveries.
export const GOLD_MIN_ACCEPTED = 3;
// Weight of the outside score in the blend.
export const OUTSIDE_WEIGHT = 0.25;

const clamp = (x: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, x));

function count(name: string, v: unknown): number {
  if (typeof v !== "number" || !Number.isInteger(v) || v < 0) {
    throw new TypeError(`${name} must be a non negative integer`);
  }
  return v;
}

function pct(name: string, v: unknown): number {
  if (typeof v !== "number" || !Number.isFinite(v) || v < 0 || v > 100) {
    throw new TypeError(`${name} must be a number from 0 to 100`);
  }
  return v;
}

export function tierOf(score: number): Tier {
  if (score >= BOUNDS.gold) return "gold";
  if (score >= BOUNDS.silver) return "silver";
  if (score >= BOUNDS.bronze) return "bronze";
  return "unproven";
}

// Score from the record alone, with one reason per contribution.
export function recordScore(r: AgentRecord): { score: number; reasons: string[] } {
  if (r === null || typeof r !== "object") throw new TypeError("record must be an object");
  const age = r.listingAgeDays;
  if (typeof age !== "number" || !Number.isFinite(age) || age < 0) {
    throw new TypeError("listingAgeDays must be a non negative number");
  }
  const acc = count("acceptedDeliveries", r.acceptedDeliveries);
  const rej = count("rejectedDeliveries", r.rejectedDeliveries);
  const adm = r.admissionTest ?? "none";
  if (adm !== "passed" && adm !== "failed" && adm !== "none") {
    throw new TypeError("admissionTest must be passed, failed or none");
  }
  const acp = r.acpScore ?? null;
  if (acp !== null) pct("acpScore", acp);

  const reasons: string[] = [];
  let s = 0;

  // Listing age: up to 10 points, full at 90 days.
  const agePts = Math.round(10 * Math.min(age, 90) / 90);
  s += agePts;
  reasons.push(`listing age ${Math.floor(age)} days: +${agePts}`);

  // Deliveries: up to 40 points from volume (8 per accepted, max 5),
  // scaled by the acceptance rate; each rejection also costs 5 points.
  const total = acc + rej;
  if (total === 0) {
    reasons.push("no reviewed delivery yet: +0");
  } else {
    const rate = acc / total;
    const volPts = Math.round(8 * Math.min(acc, 5) * rate);
    s += volPts;
    reasons.push(`${acc} accepted of ${total} reviewed (${Math.round(rate * 100)}%): +${volPts}`);
    if (rej > 0) {
      const pen = 5 * rej;
      s -= pen;
      reasons.push(`${rej} rejected: -${pen}`);
    }
  }

  // Admission test: 20 points if passed, minus 10 if failed.
  if (adm === "passed") { s += 20; reasons.push("admission test passed: +20"); }
  else if (adm === "failed") { s -= 10; reasons.push("admission test failed: -10"); }
  else reasons.push("admission test not taken: +0");

  // AIAX readiness: 10 points.
  if (r.aiaxReady === true) { s += 10; reasons.push("AIAX ready: +10"); }
  else reasons.push("AIAX not ready: +0");

  // ACP score: up to 20 points.
  if (acp === null) reasons.push("no ACP score: +0");
  else {
    const acpPts = Math.round(acp / 5);
    s += acpPts;
    reasons.push(`ACP score ${acp}: +${acpPts}`);
  }

  return { score: clamp(Math.round(s), 0, 100), reasons };
}

export function scoreAgent(record: AgentRecord, outside?: OutsideScore | null): ScoreResult {
  const base = recordScore(record);
  const reasons = [...base.reasons];
  let score = base.score;
  let tier = tierOf(score);

  // Gold needs proof of delivery, whatever the other signals say.
  if (tier === "gold" && record.acceptedDeliveries < GOLD_MIN_ACCEPTED) {
    tier = "silver";
    score = Math.min(score, BOUNDS.gold - 1);
    reasons.push(`gold needs ${GOLD_MIN_ACCEPTED} accepted deliveries: capped at silver`);
  }
  reasons.push(`record score ${score}: ${tier}`);

  if (outside != null) {
    if (typeof outside.source !== "string" || outside.source.length === 0) {
      throw new TypeError("outside.source must be a non empty string");
    }
    const o = pct("outside.score", outside.score);
    const blended = Math.round((1 - OUTSIDE_WEIGHT) * score + OUTSIDE_WEIGHT * o);
    const baseIdx = TIERS.indexOf(tier);
    let idx = TIERS.indexOf(tierOf(blended));
    // The second opinion can move the tier by one step at most.
    idx = clamp(idx, baseIdx - 1, baseIdx + 1);
    // And it can never lift past the gold proof rule.
    if (TIERS[idx] === "gold" && record.acceptedDeliveries < GOLD_MIN_ACCEPTED) idx = baseIdx;
    const newTier = TIERS[idx];
    // Keep score and tier consistent: clamp the blended score into the tier band.
    const lo = [0, BOUNDS.bronze, BOUNDS.silver, BOUNDS.gold][idx];
    const hi = [BOUNDS.bronze - 1, BOUNDS.silver - 1, BOUNDS.gold - 1, 100][idx];
    const finalScore = clamp(blended, lo, hi);
    reasons.push(`outside score ${o} from ${outside.source}, weight ${OUTSIDE_WEIGHT}: ${score} -> ${finalScore}`);
    if (newTier !== tier) reasons.push(`outside opinion moved tier ${tier} -> ${newTier}`);
    score = finalScore;
    tier = newTier;
  }

  return { score, tier, reasons };
}
```


