# KOG top holder snapshot

Reproducible snapshot of the top N holders of a Token 2022 mint. Pure TypeScript, no runtime dependency (node:crypto only).

## Interface
- `snapshot({accounts, exclusions, top = 100, mint?})` returns `{holders[], hash, excluded[], totalCounted}`.
  - `accounts`: token accounts read at one slot, `{address, owner, amount, mint?}`; `amount` is the raw u64 as a decimal string (BigInt inside, no float, no 2^53 loss).
  - `exclusions`: `[{address, label?}]`; an entry matches an owner wallet (curve, burn, project wallets) or a single token account (pool vault). Excluded balances are reported per entry for audit.
  - `holders`: `{rank, owner, amount, accounts}`, grouped by owner.
  - `hash`: sha256 hex of the canonical list, one line per holder: `rank,owner,amount\n`.
- CLI `src/cli.ts --mint <mint> [--rpc URL] [--exclusions file.json] [--top 100] [--min-slot N] [--out file.json]`: one `getProgramAccounts` on the Token 2022 program (memcmp on the mint at offset 0, jsonParsed, finalized, withContext), so the whole read comes from one slot, recorded in the output.

## Determinism
- Ranking is a total order: amount descending, then owner address in byte order (no locale compare). Ties at the cut are stable.
- Order of accounts and exclusions in the input does not change the result or the hash.
- The same token account read twice (paginated RPC) is counted once; two different reads of the same account are refused.
- Zero balance accounts never become holders. Bad addresses, non digit or over u64 amounts, accounts of another mint and a bad `top` are refused with `SnapshotInputError`.

## Tests
`npm test` (node:test + tsx), `npm run coverage` (c8 `--100`): 10 tests, 100 percent statements, branches, functions and lines. The expected hash is computed independently with Python hashlib, so the code is not tested against itself.

Live check: the CLI on PYUSD (a Token 2022 mint) read 499,835 accounts at slot 460636518 from the public mainnet RPC and produced the ranked top list with its hash.


`src/snapshot.ts`:

```ts
import { createHash } from "node:crypto";

// One SPL Token 2022 token account, as read at a given slot.
// amount is the raw base unit amount as a decimal string (u64 does not fit in a JS number).
export interface TokenAccount {
  address: string; // token account address
  owner: string; // wallet that owns the token account
  amount: string; // raw amount, decimal digits only
  mint?: string;
}

// Exclusions: curve, pools, burn, project wallets. An entry matches either the owner
// wallet or a single token account address. The label is kept for the audit trail.
export interface Exclusion {
  address: string;
  label?: string;
}

export interface Holder {
  rank: number;
  owner: string;
  amount: string;
  accounts: number; // how many token accounts were grouped under this owner
}

export interface SnapshotResult {
  holders: Holder[];
  hash: string; // sha256 hex of the canonical list
  excluded: { address: string; label: string; amount: string }[];
  totalCounted: string; // sum of all non excluded balances (not only the top)
}

const BASE58 = /^[1-9A-HJ-NP-Za-km-z]{32,44}$/;
const DIGITS = /^(0|[1-9][0-9]*)$/;
const U64_MAX = (1n << 64n) - 1n;

export class SnapshotInputError extends Error {}

function fail(msg: string): never {
  throw new SnapshotInputError(msg);
}

// Bytewise comparison on ASCII base58, independent of locale. Only used on distinct keys (Map keys).
function cmp(a: string, b: string): number {
  return a < b ? -1 : 1;
}

export function canonicalList(holders: Holder[]): string {
  return holders.map((h) => `${h.rank},${h.owner},${h.amount}\n`).join("");
}

export function snapshot(input: {
  accounts: TokenAccount[];
  exclusions?: Exclusion[];
  top?: number;
  mint?: string;
}): SnapshotResult {
  const { accounts, exclusions = [], top = 100, mint } = input;
  if (!Array.isArray(accounts)) fail("accounts must be an array");
  if (!Array.isArray(exclusions)) fail("exclusions must be an array");
  if (!Number.isInteger(top) || top < 1) fail("top must be a positive integer");
  if (mint !== undefined && !BASE58.test(mint)) fail("mint is not a base58 address");

  const excl = new Map<string, string>();
  for (const e of exclusions) {
    if (!e || typeof e.address !== "string" || !BASE58.test(e.address)) fail("bad exclusion address");
    excl.set(e.address, typeof e.label === "string" ? e.label : "");
  }

  const seen = new Map<string, string>(); // token account -> owner|amount, to catch duplicates
  const byOwner = new Map<string, { amount: bigint; accounts: number }>();
  const excludedSum = new Map<string, bigint>();
  let total = 0n;

  for (const a of accounts) {
    if (!a || typeof a.address !== "string" || !BASE58.test(a.address)) fail("bad token account address");
    if (typeof a.owner !== "string" || !BASE58.test(a.owner)) fail(`bad owner for ${a.address}`);
    if (typeof a.amount !== "string" || !DIGITS.test(a.amount)) fail(`bad amount for ${a.address}`);
    const amount = BigInt(a.amount);
    if (amount > U64_MAX) fail(`amount over u64 for ${a.address}`);
    if (mint !== undefined && a.mint !== undefined && a.mint !== mint) fail(`${a.address} is not an account of the mint`);

    // The same account read twice (RPC pagination) is ignored; two different reads are an error.
    const key = `${a.owner}|${a.amount}`;
    const prev = seen.get(a.address);
    if (prev !== undefined) {
      if (prev !== key) fail(`conflicting duplicate for ${a.address}`);
      continue;
    }
    seen.set(a.address, key);

    const hit = excl.has(a.owner) ? a.owner : excl.has(a.address) ? a.address : null;
    if (hit !== null) {
      excludedSum.set(hit, (excludedSum.get(hit) ?? 0n) + amount);
      continue;
    }
    if (amount === 0n) continue; // empty accounts never make a holder
    total += amount;
    const cur = byOwner.get(a.owner);
    if (cur) {
      cur.amount += amount;
      cur.accounts += 1;
    } else byOwner.set(a.owner, { amount, accounts: 1 });
  }

  // Rank: larger amount first; ties broken by owner address in byte order. Total order, so stable everywhere.
  const ranked = [...byOwner.entries()].sort((x, y) =>
    x[1].amount === y[1].amount ? cmp(x[0], y[0]) : x[1].amount > y[1].amount ? -1 : 1,
  );
  const holders: Holder[] = ranked.slice(0, top).map(([owner, v], i) => ({
    rank: i + 1,
    owner,
    amount: v.amount.toString(),
    accounts: v.accounts,
  }));

  const hash = createHash("sha256").update(canonicalList(holders), "utf8").digest("hex");
  const excluded = [...excludedSum.entries()]
    .sort((x, y) => cmp(x[0], y[0]))
    .map(([address, s]) => ({ address, label: excl.get(address)!, amount: s.toString() }));
  return { holders, hash, excluded, totalCounted: total.toString() };
}
