#!/usr/bin/env -S node --import tsx
// Thin CLI: fetch every Token 2022 account of a mint by RPC, then call snapshot().
// Usage: kog-snapshot --mint <mint> [--rpc URL] [--exclusions file.json] [--top 100] [--min-slot N] [--out file.json]
import { readFileSync, writeFileSync } from "node:fs";
import { snapshot, type TokenAccount, type Exclusion } from "./snapshot.ts";

const TOKEN_2022 = "TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb";

function arg(name: string, def?: string): string | undefined {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 ? process.argv[i + 1] : def;
}

export async function fetchAccounts(rpc: string, mint: string, minSlot?: number) {
  const body = {
    jsonrpc: "2.0",
    id: 1,
    method: "getProgramAccounts",
    params: [
      TOKEN_2022,
      {
        encoding: "jsonParsed",
        commitment: "finalized",
        withContext: true,
        ...(minSlot ? { minContextSlot: minSlot } : {}),
        filters: [{ memcmp: { offset: 0, bytes: mint } }], // mint is the first 32 bytes of a token account
      },
    ],
  };
  const res = await fetch(rpc, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`RPC HTTP ${res.status}`);
  const j: any = await res.json();
  if (j.error) throw new Error(`RPC error ${JSON.stringify(j.error)}`);
  const slot: number = j.result.context.slot;
  const accounts: TokenAccount[] = j.result.value.map((v: any) => {
    const info = v.account.data.parsed.info;
    return { address: v.pubkey, owner: info.owner, amount: info.tokenAmount.amount, mint: info.mint };
  });
  return { slot, accounts };
}

async function main() {
  const mint = arg("mint");
  if (!mint) throw new Error("--mint is required");
  const rpc = arg("rpc", "https://api.mainnet-beta.solana.com")!;
  const exclFile = arg("exclusions");
  const exclusions: Exclusion[] = exclFile ? JSON.parse(readFileSync(exclFile, "utf8")) : [];
  const top = Number(arg("top", "100"));
  const minSlot = arg("min-slot") ? Number(arg("min-slot")) : undefined;
  const { slot, accounts } = await fetchAccounts(rpc, mint, minSlot);
  const out = { mint, slot, accountsRead: accounts.length, ...snapshot({ accounts, exclusions, top, mint }) };
  const text = JSON.stringify(out, null, 2) + "\n";
  const file = arg("out");
  if (file) writeFileSync(file, text);
  else process.stdout.write(text);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((e) => {
    console.error(String(e?.message ?? e));
    process.exit(1);
  });
}
