# Cerberus chamber 1: identity of a listed LAX agent

Pure TypeScript module that proves a bidding agent controls its LAX listing.
No network. viem is used only for offline EIP-191 signature recovery.

## Interface
- `createChallenge({did, listingId, now, ttlMs?, nonce?})` returns `{did, listingId, nonce, issuedAt, expiresAt, message}`. Nonce: 32 random bytes (injectable for tests). Default validity 5 minutes.
- `verifyChallenge({challenge, signature, ownerAddress, now, usedNonces?})` returns `Promise<{ok, reason, signer?}>`. Never throws on bad input.

Reasons: `ok`, `malformed_challenge`, `tampered`, `not_yet_valid`, `expired`, `replayed`, `malformed_signature`, `invalid_owner_address`, `wrong_signer`.

## Security choices
- The signed text is rebuilt from the fields and must match `message` exactly, so a changed DID or listing id is caught as `tampered` before any crypto. If an attacker also rebuilds the text, the signature no longer recovers the owner (`wrong_signer`).
- Field values must be one line: no newline injection into the signed text.
- Expiry is exclusive (`now >= expiresAt` is expired); a challenge used before `issuedAt` is refused.
- The nonce is consumed only after a valid signature, so a forged request cannot burn the real owner's nonce. Any store with `has/add` works (a `Set`, or a shared store in production).
- Owner address comparison is checksum insensitive.

## Tests
`npm test` (node:test + tsx), `npm run coverage` (c8 with `--100`): 10 tests, 100 percent statements, branches, functions and lines. Covers valid signature, wrong signer, expired (boundary), not yet valid, replayed nonce, tampered DID (both variants), malformed inputs.


`src/identity.ts`:

```ts
// Cerberus chamber 1: prove that a bidding agent controls its LAX listing.
// Pure module, no network. The owner signs the challenge text with EIP-191
// (personal_sign); we recover the signer offline with viem and compare.
import { recoverMessageAddress, isAddress, getAddress, isHex } from 'viem';

export const DEFAULT_TTL_MS = 5 * 60 * 1000;
const HEADER = 'LAX listing ownership challenge';

export interface Challenge {
  did: string;
  listingId: string;
  nonce: string; // 32 random bytes, 0x hex
  issuedAt: string; // ISO 8601
  expiresAt: string; // ISO 8601
  message: string; // exact text the owner signs
}

export type Reason =
  | 'ok'
  | 'malformed_challenge'
  | 'tampered'
  | 'not_yet_valid'
  | 'expired'
  | 'replayed'
  | 'malformed_signature'
  | 'invalid_owner_address'
  | 'wrong_signer';

export interface VerifyResult {
  ok: boolean;
  reason: Reason;
  signer?: string;
}

/** Nonce memory used for replay protection. A Set works; so does any store with has/add. */
export interface NonceStore {
  has(nonce: string): boolean;
  add(nonce: string): unknown;
}

export function challengeText(c: Omit<Challenge, 'message'>): string {
  return [
    HEADER,
    `did: ${c.did}`,
    `listing: ${c.listingId}`,
    `nonce: ${c.nonce}`,
    `issued: ${c.issuedAt}`,
    `expires: ${c.expiresAt}`,
  ].join('\n');
}

function randomNonce(): string {
  const b = new Uint8Array(32);
  globalThis.crypto.getRandomValues(b);
  return '0x' + Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('');
}

const NONCE_RE = /^0x[0-9a-f]{64}$/;
// Field values must stay on one line so the text cannot be forged by injection.
const SAFE_RE = /^[^\r\n]{1,256}$/;

export function createChallenge(args: {
  did: string;
  listingId: string;
  now: Date | number;
  ttlMs?: number;
  nonce?: string; // injectable for deterministic tests
}): Challenge {
  const { did, listingId } = args;
  if (!SAFE_RE.test(did) || !did.startsWith('did:')) throw new Error('did must be a one line did: string');
  if (!SAFE_RE.test(listingId)) throw new Error('listingId must be a non empty one line string');
  const ttl = args.ttlMs ?? DEFAULT_TTL_MS;
  if (!Number.isInteger(ttl) || ttl <= 0) throw new Error('ttlMs must be a positive integer');
  const nonce = args.nonce ?? randomNonce();
  if (!NONCE_RE.test(nonce)) throw new Error('nonce must be 32 bytes lowercase hex');
  const t = typeof args.now === 'number' ? args.now : args.now.getTime();
  const base = {
    did,
    listingId,
    nonce,
    issuedAt: new Date(t).toISOString(),
    expiresAt: new Date(t + ttl).toISOString(),
  };
  return { ...base, message: challengeText(base) };
}

function isWellFormed(c: unknown): c is Challenge {
  if (!c || typeof c !== 'object') return false;
  const o = c as Record<string, unknown>;
  for (const k of ['did', 'listingId', 'nonce', 'issuedAt', 'expiresAt', 'message']) {
    if (typeof o[k] !== 'string') return false;
  }
  return (
    SAFE_RE.test(o.did as string) &&
    SAFE_RE.test(o.listingId as string) &&
    NONCE_RE.test(o.nonce as string) &&
    !Number.isNaN(Date.parse(o.issuedAt as string)) &&
    !Number.isNaN(Date.parse(o.expiresAt as string))
  );
}

/**
 * Verify that `ownerAddress` signed `challenge` (EIP-191).
 * Order: shape, integrity, time window, replay, signature. The nonce is only
 * consumed after a valid signature, so a forged request cannot burn the nonce
 * of the real owner.
 */
export async function verifyChallenge(args: {
  challenge: unknown;
  signature: unknown;
  ownerAddress: unknown;
  now: Date | number;
  usedNonces?: NonceStore;
}): Promise<VerifyResult> {
  const { challenge, signature, ownerAddress, usedNonces } = args;
  if (!isWellFormed(challenge)) return { ok: false, reason: 'malformed_challenge' };
  if (challengeText(challenge) !== challenge.message) return { ok: false, reason: 'tampered' };

  const t = typeof args.now === 'number' ? args.now : args.now.getTime();
  if (t < Date.parse(challenge.issuedAt)) return { ok: false, reason: 'not_yet_valid' };
  if (t >= Date.parse(challenge.expiresAt)) return { ok: false, reason: 'expired' };
  if (usedNonces?.has(challenge.nonce)) return { ok: false, reason: 'replayed' };

  if (typeof ownerAddress !== 'string' || !isAddress(ownerAddress, { strict: false })) {
    return { ok: false, reason: 'invalid_owner_address' };
  }
  if (typeof signature !== 'string' || !isHex(signature) || signature.length !== 132) {
    return { ok: false, reason: 'malformed_signature' };
  }

  let signer: string;
  try {
    signer = await recoverMessageAddress({ message: challenge.message, signature });
  } catch {
    return { ok: false, reason: 'malformed_signature' };
  }
  if (getAddress(signer) !== getAddress(ownerAddress)) {
    return { ok: false, reason: 'wrong_signer', signer };
  }
  usedNonces?.add(challenge.nonce);
  return { ok: true, reason: 'ok', signer };
}
