import { test } from 'node:test';
import assert from 'node:assert/strict';
import { privateKeyToAccount } from 'viem/accounts';
import { createChallenge, verifyChallenge, challengeText } from '../src/identity.ts';

// Throwaway test keys, generated for these tests only and never funded.
const owner = privateKeyToAccount(`0x${'11'.repeat(32)}`);
const other = privateKeyToAccount(`0x${'22'.repeat(32)}`);
const NOW = Date.parse('2026-10-24T12:00:00.000Z');
const NONCE = '0x' + 'ab'.repeat(32);
const DID = 'did:lax:agent-survie';
const LISTING = 'lax-ext-5beb2d75757a';

const fresh = () => createChallenge({ did: DID, listingId: LISTING, now: NOW, nonce: NONCE });

test('valid signature from the listing owner passes', async () => {
  const c = fresh();
  const signature = await owner.signMessage({ message: c.message });
  const r = await verifyChallenge({ challenge: c, signature, ownerAddress: owner.address, now: NOW + 1000 });
  assert.deepEqual(r, { ok: true, reason: 'ok', signer: owner.address });
});

test('owner address comparison ignores checksum case', async () => {
  const c = fresh();
  const signature = await owner.signMessage({ message: c.message });
  const r = await verifyChallenge({ challenge: c, signature, ownerAddress: owner.address.toLowerCase(), now: NOW });
  assert.equal(r.ok, true);
});

test('wrong signer is refused and the nonce is not consumed', async () => {
  const c = fresh();
  const used = new Set<string>();
  const bad = await other.signMessage({ message: c.message });
  const r = await verifyChallenge({ challenge: c, signature: bad, ownerAddress: owner.address, now: NOW, usedNonces: used });
  assert.equal(r.reason, 'wrong_signer');
  assert.equal(r.signer, other.address);
  assert.equal(used.size, 0);
  const good = await owner.signMessage({ message: c.message });
  const r2 = await verifyChallenge({ challenge: c, signature: good, ownerAddress: owner.address, now: NOW, usedNonces: used });
  assert.equal(r2.ok, true);
});

test('expired challenge is refused, boundary included', async () => {
  const c = fresh();
  const signature = await owner.signMessage({ message: c.message });
  const atExpiry = Date.parse(c.expiresAt);
  assert.equal((await verifyChallenge({ challenge: c, signature, ownerAddress: owner.address, now: atExpiry - 1 })).ok, true);
  const r = await verifyChallenge({ challenge: c, signature, ownerAddress: owner.address, now: new Date(atExpiry) });
  assert.deepEqual(r, { ok: false, reason: 'expired' });
});

test('challenge used before issuance is refused', async () => {
  const c = fresh();
  const signature = await owner.signMessage({ message: c.message });
  const r = await verifyChallenge({ challenge: c, signature, ownerAddress: owner.address, now: NOW - 1 });
  assert.equal(r.reason, 'not_yet_valid');
});

test('replayed nonce is refused', async () => {
  const c = fresh();
  const used = new Set<string>();
  const signature = await owner.signMessage({ message: c.message });
  assert.equal((await verifyChallenge({ challenge: c, signature, ownerAddress: owner.address, now: NOW, usedNonces: used })).ok, true);
  const r = await verifyChallenge({ challenge: c, signature, ownerAddress: owner.address, now: NOW + 5, usedNonces: used });
  assert.deepEqual(r, { ok: false, reason: 'replayed' });
});

test('tampered DID is refused (fields no longer match the signed text)', async () => {
  const c = fresh();
  const signature = await owner.signMessage({ message: c.message });
  const r = await verifyChallenge({ challenge: { ...c, did: 'did:lax:someone-else' }, signature, ownerAddress: owner.address, now: NOW });
  assert.deepEqual(r, { ok: false, reason: 'tampered' });
});

test('tampered DID with a rebuilt message fails the signature', async () => {
  const c = fresh();
  const signature = await owner.signMessage({ message: c.message });
  const forged = { ...c, did: 'did:lax:someone-else' };
  forged.message = challengeText(forged);
  const r = await verifyChallenge({ challenge: forged, signature, ownerAddress: owner.address, now: NOW });
  assert.equal(r.reason, 'wrong_signer');
});

test('malformed inputs are refused without throwing', async () => {
  const c = fresh();
  const signature = await owner.signMessage({ message: c.message });
  const v = (o: object) => verifyChallenge({ challenge: c, signature, ownerAddress: owner.address, now: NOW, ...o });
  assert.equal((await v({ challenge: null })).reason, 'malformed_challenge');
  assert.equal((await v({ challenge: 'x' })).reason, 'malformed_challenge');
  assert.equal((await v({ challenge: { ...c, nonce: 'zz' } })).reason, 'malformed_challenge');
  assert.equal((await v({ challenge: { ...c, did: 'a\nb' } })).reason, 'malformed_challenge');
  assert.equal((await v({ challenge: { ...c, issuedAt: 'never' } })).reason, 'malformed_challenge');
  assert.equal((await v({ challenge: { ...c, listingId: 7 } })).reason, 'malformed_challenge');
  assert.equal((await v({ ownerAddress: 'nope' })).reason, 'invalid_owner_address');
  assert.equal((await v({ ownerAddress: 42 })).reason, 'invalid_owner_address');
  assert.equal((await v({ signature: '0x1234' })).reason, 'malformed_signature');
  assert.equal((await v({ signature: 12 })).reason, 'malformed_signature');
  assert.equal((await v({ signature: '0x' + '00'.repeat(65) })).reason, 'malformed_signature');
