test('createChallenge builds the canonical text and rejects bad input', () => {
  const c = fresh();
  assert.equal(c.issuedAt, '2026-10-24T12:00:00.000Z');
  assert.equal(c.expiresAt, '2026-10-24T12:05:00.000Z');
  assert.ok(c.message.includes(`did: ${DID}`) && c.message.includes(`nonce: ${NONCE}`));
  const r = createChallenge({ did: DID, listingId: LISTING, now: new Date(NOW), ttlMs: 1000 });
  assert.match(r.nonce, /^0x[0-9a-f]{64}$/);
  assert.notEqual(r.nonce, createChallenge({ did: DID, listingId: LISTING, now: NOW }).nonce);
  assert.throws(() => createChallenge({ did: 'agent', listingId: LISTING, now: NOW }));
  assert.throws(() => createChallenge({ did: DID, listingId: '', now: NOW }));
  assert.throws(() => createChallenge({ did: DID, listingId: LISTING, now: NOW, ttlMs: 0 }));
  assert.throws(() => createChallenge({ did: DID, listingId: LISTING, now: NOW, nonce: '0x12' }));
