# rankBids: CEO ranking scorer for LAX tender bids

Pure TypeScript, no dependency at runtime, no I/O, no clock, no randomness.

`rankBids(bundle, bids, records) -> [{bid_id, rank, score, reason}]`

Score out of 100: price against the ceiling 25 (linear, 5 at the ceiling, 25 at zero), tests 25, scope coverage 15 (spec terms found in the approach), track record 25 (Laplace smoothed acceptance rate, unknown agents neutral), Cerberus tier 10.

Ordering is lexicographic: (1) bids within the ceiling first, (2) bids that commit to tests before bids that do not, (3) score, (4) lower price, (5) bid_id. Rule (2) makes "a cheaper bid with no tests never outranks a tested one" hold by construction, not by weight tuning; a property test checks it for prices 0 to 100 and a perfect record on the untested side. Negated mentions ("no tests", "without tests") do not count as tests.

Every reason is at least 10 words, explains each component with its points, uses Latin digits and no long dashes.

`npm install && npm test` (node:test with tsx, 12 tests).


`src/rankBids.ts`:

```ts
// Pure ranking of tender bids. No I/O, no clock, no randomness.
// Score out of 100: price 25, approach 40 (tests 25, scope 15), record 25, Cerberus tier 10.
// Hard rule: a bid without tests never outranks a bid with tests (tested bids sort first),
// so a cheaper untested bid can never win on price alone.

export interface Bundle {
  job_id: string;
  ceiling_usdc: number;
  scope_terms?: string[]; // words from the spec that a focused approach should mention
}

export interface Bid {
  bid_id: string;
  agent_id: string;
  price_usdc: number;
  approach_md: string;
}

export interface AgentRecord {
  accepted: number;  // deliveries accepted
  rejected: number;  // deliveries rejected or abandoned
  cerberus_tier?: number; // 0 (none) .. 3 (highest)
}

export interface Ranked {
  bid_id: string;
  rank: number;
  score: number;
  reason: string;
}

const TEST_PATTERNS = [
  /\btests?\b/i, /\bnode:test\b/i, /\bvitest\b/i, /\bjest\b/i, /\bmocha\b/i,
  /\bunit test/i, /\bfixtures?\b/i, /\bassert/i,
];

export function hasTests(approach: string): boolean {
  // A negated mention ("no tests", "without tests") does not count.
  const cleaned = approach.replace(/\b(no|without|skip(ping)?)\s+(unit\s+)?tests?\b/gi, " ");
  return TEST_PATTERNS.some((re) => re.test(cleaned));
}

function round2(x: number): number {
  return Math.round(x * 100) / 100;
}

export function priceScore(price: number, ceiling: number): number {
  if (!(ceiling > 0) || !(price >= 0) || price > ceiling) return 0;
  // Linear: at the ceiling 5 points, free 25 points. A price is never worth more than 25.
  return round2(5 + 20 * (1 - price / ceiling));
}

export function scopeScore(approach: string, terms: string[] | undefined): number {
  if (!terms || terms.length === 0) return approach.trim().length >= 200 ? 15 : 7.5;
  const text = approach.toLowerCase();
  const uniq = [...new Set(terms.map((t) => t.toLowerCase()))].sort();
  const hits = uniq.filter((t) => text.includes(t)).length;
  return round2((15 * hits) / uniq.length);
}

export function recordScore(rec: AgentRecord | undefined): number {
  if (!rec) return 10; // unknown agent: neutral, below a good record, above a bad one
  const a = Math.max(0, rec.accepted | 0);
  const r = Math.max(0, rec.rejected | 0);
  // Laplace smoothed acceptance rate, so one lucky delivery is not a perfect record.
  return round2(25 * ((a + 1) / (a + r + 2)) * (a + r === 0 ? 0.8 : 1));
}

export function tierScore(rec: AgentRecord | undefined): number {
  const t = Math.min(3, Math.max(0, Math.floor(rec?.cerberus_tier ?? 0)));
  return round2((10 * t) / 3);
}

export function rankBids(
  bundle: Bundle,
  bids: Bid[],
  records: Record<string, AgentRecord>,
): Ranked[] {
  const rows = bids.map((b) => {
    const rec = Object.prototype.hasOwnProperty.call(records, b.agent_id) ? records[b.agent_id] : undefined;
    const overCeiling = !(b.price_usdc <= bundle.ceiling_usdc) || !(b.price_usdc >= 0);
    const tested = hasTests(b.approach_md);
    const p = priceScore(b.price_usdc, bundle.ceiling_usdc);
    const t = tested ? 25 : 0;
    const s = scopeScore(b.approach_md, bundle.scope_terms);
    const r = recordScore(rec);
    const c = tierScore(rec);
    const score = overCeiling ? 0 : round2(p + t + s + r + c);
    return { b, rec, overCeiling, tested, p, s, r, c, score };
  });

  rows.sort((x, y) =>
    Number(x.overCeiling) - Number(y.overCeiling) ||
    Number(y.tested) - Number(x.tested) ||
    y.score - x.score ||
    x.b.price_usdc - y.b.price_usdc ||
    (x.b.bid_id < y.b.bid_id ? -1 : x.b.bid_id > y.b.bid_id ? 1 : 0),
  );

  return rows.map((row, i) => ({
    bid_id: row.b.bid_id,
    rank: i + 1,
    score: row.score,
    reason: reasonFor(row, bundle),
  }));
}

function reasonFor(
  row: { b: Bid; rec: AgentRecord | undefined; overCeiling: boolean; tested: boolean; p: number; s: number; r: number; c: number; score: number },
  bundle: Bundle,
): string {
  const { b, rec } = row;
  if (row.overCeiling) {
    return `Ineligible because the price of ${b.price_usdc} USDC is above the ceiling of ${bundle.ceiling_usdc} USDC or is not a valid amount, so it ranks last.`;
  }
  const parts: string[] = [];
  parts.push(`Price ${b.price_usdc} USDC against a ceiling of ${bundle.ceiling_usdc} USDC earns ${row.p} of 25 points.`);
  parts.push(row.tested
    ? "The approach commits to tests, which earns 25 of 25 points."
    : "The approach does not commit to tests, so it earns 0 of 25 points and ranks below every tested bid.");
  parts.push(`Scope coverage earns ${row.s} of 15 points.`);
  parts.push(rec
    ? `Track record of ${rec.accepted} accepted and ${rec.rejected} rejected deliveries earns ${row.r} of 25 points, Cerberus tier ${rec.cerberus_tier ?? 0} earns ${row.c} of 10.`
    : `No track record is known for this agent, so it gets a neutral ${row.r} of 25 points and 0 of 10 for tier.`);
  parts.push(`Total ${row.score} of 100.`);
  return parts.join(" ");
}
