`verifier.js`:

```js
// Charter attestation verifier: reads an EAS attestation on Base or Base Sepolia,
// fetches every text from IPFS, recomputes its sha256 and reports match or mismatch.
// Plain ES module, no dependency: runs in the browser and in Node 20 (globalThis.crypto.subtle).

export const SCHEMA = "string version,string date,string[] names,bytes32[] digests,string[] cids";
export const EAS_ADDRESS = "0x4200000000000000000000000000000000000021";
export const NETWORKS = {
  base: { chainId: 8453, rpcUrl: "https://mainnet.base.org" },
  "base-sepolia": { chainId: 84532, rpcUrl: "https://sepolia.base.org" },
};
const GET_ATTESTATION = "0xa3112a64"; // getAttestation(bytes32)
const ZERO32 = "0x" + "0".repeat(64);

const hexToBytes = (h) => {
  const out = new Uint8Array(h.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(h.slice(i * 2, i * 2 + 2), 16);
  return out;
};
const bytesToHex = (b) => Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");

// Strict ABI reader over a hex string without 0x: every offset and length is bounds checked.
function reader(h) {
  const words = h.length / 2;
  const num = (byteOff) => {
    if (byteOff < 0 || byteOff * 2 + 64 > h.length) throw new Error("malformed_data");
    const v = BigInt("0x" + h.slice(byteOff * 2, byteOff * 2 + 64));
    if (v > BigInt(words)) throw new Error("malformed_data");
    return Number(v);
  };
  const word = (byteOff) => {
    if (byteOff < 0 || byteOff * 2 + 64 > h.length) throw new Error("malformed_data");
    return h.slice(byteOff * 2, byteOff * 2 + 64);
  };
  const bytes = (o) => {
    const len = num(o), s = (o + 32) * 2;
    if (s + len * 2 > h.length) throw new Error("malformed_data");
    return hexToBytes(h.slice(s, s + len * 2));
  };
  const str = (o) => new TextDecoder("utf-8", { fatal: true }).decode(bytes(o));
  return { num, word, bytes, str };
}

export function decodeCharterData(dataHex) {
  if (typeof dataHex !== "string") throw new Error("malformed_data");
  const h = dataHex.replace(/^0x/, "").toLowerCase();
  if (!/^[0-9a-f]*$/.test(h) || h.length % 64 !== 0 || h.length < 5 * 64) throw new Error("malformed_data");
  const r = reader(h);
  const strArr = (o) => { const n = r.num(o); const out = []; for (let i = 0; i < n; i++) out.push(r.str(o + 32 + r.num(o + 32 + 32 * i))); return out; };
  const b32Arr = (o) => { const n = r.num(o); const out = []; for (let i = 0; i < n; i++) out.push("0x" + r.word(o + 32 + 32 * i)); return out; };
  return { version: r.str(r.num(0)), date: r.str(r.num(32)), names: strArr(r.num(64)), digests: b32Arr(r.num(96)), cids: strArr(r.num(128)) };
}

// Decodes the return value of EAS getAttestation(bytes32): one dynamic tuple
// (uid, schema, time, expirationTime, revocationTime, refUID, recipient, attester, revocable, data).
export function decodeAttestation(retHex) {
  const h = String(retHex).replace(/^0x/, "").toLowerCase();
  if (!/^[0-9a-f]*$/.test(h) || h.length % 64 !== 0 || h.length < 64 * 11) throw new Error("malformed_attestation");
  try {
    const r = reader(h);
    const t = r.num(0);
    const w = (i) => r.word(t + 32 * i);
    return {
      uid: "0x" + w(0),
      schema: "0x" + w(1),
      time: Number(BigInt("0x" + w(2))),
      expirationTime: Number(BigInt("0x" + w(3))),
      revocationTime: Number(BigInt("0x" + w(4))),
      recipient: "0x" + w(6).slice(24),
      attester: "0x" + w(7).slice(24),
      data: "0x" + bytesToHex(r.bytes(t + r.num(t + 32 * 9))),
    };
  } catch {
    throw new Error("malformed_attestation");
  }
}

export async function sha256Hex(bytes) {
  const d = await globalThis.crypto.subtle.digest("SHA-256", bytes);
  return "0x" + bytesToHex(new Uint8Array(d));
}

const errMsg = (e) => (e && e.message ? e.message : String(e));

export async function verifyCharter({ uid, network, rpc, ipfs }) {
  const attestation = { uid: typeof uid === "string" ? uid.toLowerCase() : String(uid), attester: null, time: null, revoked: null };
  const fail = (reason, texts = []) => ({ ok: false, reason, attestation, texts });
  if (!NETWORKS[network]) return fail("unknown network: use base or base-sepolia");
  if (typeof uid !== "string" || !/^0x[0-9a-fA-F]{64}$/.test(uid)) return fail("invalid uid: expected 0x and 64 hex characters");
  if (typeof rpc !== "function" || typeof ipfs !== "function") return fail("rpc and ipfs functions are required");

  let ret;
  try {
    ret = await rpc("eth_call", [{ to: EAS_ADDRESS, data: GET_ATTESTATION + uid.slice(2).toLowerCase() }, "latest"]);
  } catch (e) {
    return fail("rpc error: " + errMsg(e));
  }
  let a;
  try { a = decodeAttestation(ret); } catch { return fail("rpc returned an unreadable attestation"); }
  if (a.uid === ZERO32) return fail("attestation not found on " + network);
  attestation.attester = a.attester;
  attestation.time = a.time;
  attestation.revoked = a.revocationTime !== 0;
  if (attestation.revoked) return fail("attestation revoked at " + new Date(a.revocationTime * 1000).toISOString());

  let d;
  try { d = decodeCharterData(a.data); } catch { return fail("attestation data does not match the charter schema"); }
  if (d.names.length !== d.digests.length || d.names.length !== d.cids.length || d.names.length === 0) {
    return fail("attestation arrays are empty or not parallel");
  }

  const texts = await Promise.all(d.names.map(async (name, i) => {
    const t = { name, cid: d.cids[i], expected: d.digests[i], actual: null, match: false };
    try {
      const body = await ipfs(t.cid);
      if (!(body instanceof Uint8Array)) throw new Error("ipfs did not return bytes");
      t.actual = await sha256Hex(body);
      t.match = t.actual === t.expected;
    } catch (e) {
      t.error = "cannot fetch " + t.cid + ": " + errMsg(e);
    }
    return t;
  }));
  const ok = texts.every((t) => t.match);
  const out = { ok, attestation, texts };
  if (!ok) {
    const bad = texts.filter((t) => !t.match).map((t) => t.name + (t.error ? " (not fetched)" : " (mismatch)"));
    out.reason = "not verified: " + bad.join(", ");
  }
  return out;
}

// fetch based helpers used by the page.
export function fetchRpc(url) {
  let id = 0;
  return async (method, params) => {
    const res = await fetch(url, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ jsonrpc: "2.0", id: ++id, method, params }) });
    if (!res.ok) throw new Error("HTTP " + res.status);
    const j = await res.json();
    if (j.error) throw new Error(j.error.message || "rpc error");
    return j.result;
  };
}
export function fetchIpfs(gateway) {
  const base = gateway.endsWith("/") ? gateway : gateway + "/";
  return async (cid) => {
    const res = await fetch(base + encodeURIComponent(cid));
    if (!res.ok) throw new Error("HTTP " + res.status);
    return new Uint8Array(await res.arrayBuffer());
  };
}
