    <br><small>attester <code>${esc(a.attester ?? "n/a")}</code>, time ${a.time ? new Date(a.time * 1000).toISOString() : "n/a"}, revoked ${a.revoked ?? "n/a"}</small></div>`;
  for (const t of r.texts) {
    html += `<div class="card ${t.match ? "ok" : "bad"}"><strong>${esc(t.name)}: ${t.match ? "match" : t.error ? "not fetched" : "mismatch"}</strong>
      <br>cid <code>${esc(t.cid)}</code><br>expected <code>${esc(t.expected)}</code><br>actual <code>${esc(t.actual ?? "n/a")}</code>${t.error ? "<br>" + esc(t.error) : ""}</div>`;
  }
  $("out").innerHTML = html; $("go").disabled = false;
});
