# One Charter attestation builder

Hashes the Charter, the Constitution and the SOUL texts, takes their IPFS ids, and outputs one EAS attestation payload for one schema.

```ts
buildAttestation({ texts, cids, version, date }) -> { schema, data, digests }
```

- `schema` is fixed: `string version,string date,string[] names,bytes32[] digests,string[] cids` (the same schema the Charter verifier page decodes).
- `texts` and `cids` are keyed `charter`, `constitution`, `soul`; a text is a string (hashed as UTF-8) or raw bytes (hashed as is, so it matches the exact bytes stored under the CID).
- `digests` are sha256, `0x` + 64 lowercase hex; `data` is the ABI encoding of the 5 fields, names in the fixed order charter, constitution, soul, ready for EAS `attest`.
- `decodeCharterData(data)` reads it back (strict bounds checks, throws `malformed_data`).
- Refuses a missing, empty or unknown text, a malformed CID (CIDv0 `Qm...` or CIDv1 base32 `b...`), an empty version or an impossible date.

Pure TypeScript on `node:crypto`, no runtime dependency, no network, no key.

## Tests

`npm install && npm test` (node:test with tsx): 10 passing, offline. The ABI test compares against a reference encoding produced independently with Python `eth_abi.encode` for the same inputs, so the encoder is not tested against itself.


`src/charter.ts`:

```ts
// One Charter attestation builder: sha256 of each text + one EAS payload for one schema.
import { createHash } from "node:crypto";

export const SCHEMA = "string version,string date,string[] names,bytes32[] digests,string[] cids";
export const NAMES = ["charter", "constitution", "soul"] as const;
export type TextName = (typeof NAMES)[number];
export type TextInput = string | Uint8Array;

export interface BuildInput {
  texts: Record<TextName, TextInput>;
  cids: Record<TextName, string>;
  version: string;
  date: string; // YYYY-MM-DD
}
export interface Attestation {
  schema: string;
  data: string; // 0x ABI encoding of the schema fields
  digests: Record<TextName, string>; // 0x + 64 lowercase hex
}

const enc = new TextEncoder();
const bytesOf = (t: TextInput): Uint8Array => (typeof t === "string" ? enc.encode(t) : t);
const toHex = (b: Uint8Array): string => Buffer.from(b).toString("hex");

export function sha256Hex(t: TextInput): string {
  return "0x" + createHash("sha256").update(bytesOf(t)).digest("hex");
}

// CIDv0 (Qm + 44 base58) or CIDv1 base32 lower (b + 58 or more [a-z2-7]).
const CID_RE = /^(Qm[1-9A-HJ-NP-Za-km-z]{44}|b[a-z2-7]{58,})$/;
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const validDay = (d: string): boolean => { const t = new Date(d + "T00:00:00Z"); return !isNaN(t.getTime()) && t.toISOString().slice(0, 10) === d; };

// ---- minimal ABI encoder for the schema types (string, string[], bytes32[]) ----
const word = (n: number): string => n.toString(16).padStart(64, "0");
const pad32 = (hex: string): string => hex.padEnd(Math.ceil(hex.length / 64) * 64, "0");
const encString = (s: string): string => { const h = toHex(enc.encode(s)); return word(h.length / 2) + pad32(h); };
function encStringArray(a: string[]): string {
  const tails = a.map(encString);
  let off = a.length * 32, heads = "";
  for (const t of tails) { heads += word(off); off += t.length / 2; }
  return word(a.length) + heads + tails.join("");
}
const encBytes32Array = (a: string[]): string => word(a.length) + a.map((d) => d.slice(2)).join("");

export function encodeCharterData(f: { version: string; date: string; names: string[]; digests: string[]; cids: string[] }): string {
  const tails = [encString(f.version), encString(f.date), encStringArray(f.names), encBytes32Array(f.digests), encStringArray(f.cids)];
  let off = 5 * 32, heads = "";
  for (const t of tails) { heads += word(off); off += t.length / 2; }
  return "0x" + heads + tails.join("");
}

// ---- decoder (to read back and for the verifier page) ----
export function decodeCharterData(dataHex: string): { version: string; date: string; names: string[]; digests: string[]; cids: string[] } {
  const h = dataHex.replace(/^0x/, "").toLowerCase();
  if (!/^[0-9a-f]*$/.test(h) || h.length % 64 !== 0 || h.length < 5 * 64) throw new Error("malformed_data");
  const num = (byteOff: number): number => {
    if (byteOff * 2 + 64 > h.length) throw new Error("malformed_data");
    const v = BigInt("0x" + h.slice(byteOff * 2, byteOff * 2 + 64));
    if (v > BigInt(h.length / 2)) throw new Error("malformed_data");
    return Number(v);
  };
  const str = (o: number): string => {
    const len = num(o); const s = (o + 32) * 2;
    if (s + len * 2 > h.length) throw new Error("malformed_data");
    return new TextDecoder("utf-8", { fatal: true }).decode(Buffer.from(h.slice(s, s + len * 2), "hex"));
  };
  const strArr = (o: number): string[] => { const n = num(o); const out: string[] = []; for (let i = 0; i < n; i++) out.push(str(o + 32 + num(o + 32 + 32 * i))); return out; };
  const b32Arr = (o: number): string[] => { const n = num(o); const out: string[] = []; for (let i = 0; i < n; i++) { const s = (o + 32 + 32 * i) * 2; if (s + 64 > h.length) throw new Error("malformed_data"); out.push("0x" + h.slice(s, s + 64)); } return out; };
  return { version: str(num(0)), date: str(num(32)), names: strArr(num(64)), digests: b32Arr(num(96)), cids: strArr(num(128)) };
}

export function buildAttestation(input: BuildInput): Attestation {
  const { texts, cids, version, date } = input ?? ({} as BuildInput);
  if (typeof version !== "string" || version.trim() === "") throw new Error("invalid_version");
  if (typeof date !== "string" || !DATE_RE.test(date) || !validDay(date)) throw new Error("invalid_date");
  for (const k of Object.keys(texts ?? {})) if (!(NAMES as readonly string[]).includes(k)) throw new Error("unknown_text:" + k);
  for (const k of Object.keys(cids ?? {})) if (!(NAMES as readonly string[]).includes(k)) throw new Error("unknown_cid:" + k);
  const digests = {} as Record<TextName, string>;
  for (const n of NAMES) {
    const t = texts?.[n];
    if (typeof t !== "string" && !(t instanceof Uint8Array)) throw new Error("missing_text:" + n);
    if (bytesOf(t).length === 0) throw new Error("empty_text:" + n);
    const c = cids?.[n];
    if (typeof c !== "string" || !CID_RE.test(c)) throw new Error("invalid_cid:" + n);
    digests[n] = sha256Hex(t);
  }
  const data = encodeCharterData({ version, date, names: [...NAMES], digests: NAMES.map((n) => digests[n]), cids: NAMES.map((n) => cids[n]) });
  return { schema: SCHEMA, data, digests };
}
```

