# siws-verify: Sign in with Solana

Message format, ed25519 verification, replay guard and allowlist. Pure TypeScript on node:crypto, no runtime dependency, no RPC.

## Interface
- `createMessage({domain, address, nonce, issuedAt, expirationTime, statement?, uri?, chainId?}) -> string`
- `verify({message, signature, address, domain, allowlist?, now?, seen, clockSkewMs?}) -> {ok, reason, fields?}`
- `parseMessage(message) -> fields | null` (strict: fixed field order, no unknown or duplicate fields)

Reasons: ok, malformed_message, wrong_domain, invalid_address, address_mismatch, not_yet_valid, expired, malformed_signature, replayed_nonce, not_on_allowlist, bad_signature.

## Design choices
- Cheap checks first, ed25519 last. The nonce is recorded in `seen` only after a valid signature, so a forged request cannot burn a real user's nonce.
- `seen` is any `{has, add}` (a Set, or a Redis wrapper). Time is passed in (`now`), so tests are deterministic.
- Signature: base58 string or 64 raw bytes. Anything else is malformed_signature, not a thrown error.

## Tests
`npm test` (node:test with tsx): 16 passing. Valid, raw bytes, wrong domain, expired, future issuedAt, replayed nonce, forged signature does not burn the nonce, address not on the allowlist, no allowlist, malformed signatures, signature from another key, tampered message, address mismatch, malformed messages, createMessage input checks and round trip, base58 leading zeros.


`src/siws.ts`:

```ts
// Sign in with Solana: create a message, verify it (ed25519), guard replays, check an allowlist.
// Pure: no RPC, no network. Time and the seen nonce store are passed in.
import { createPublicKey, verify as edVerify } from "node:crypto";
import { b58decode } from "./base58.ts";

export interface MessageParams {
  domain: string;          // e.g. "lax.kognai.ai"
  address: string;         // base58 Solana public key
  nonce: string;           // >= 8 alphanumeric chars
  issuedAt: string;        // ISO 8601
  expirationTime: string;  // ISO 8601
  statement?: string;
  uri?: string;
  chainId?: string;        // e.g. "mainnet"
}

export type Reason =
  | "ok" | "malformed_message" | "wrong_domain" | "address_mismatch" | "invalid_address"
  | "not_yet_valid" | "expired" | "replayed_nonce" | "not_on_allowlist"
  | "malformed_signature" | "bad_signature";

export interface NonceStore { has(n: string): boolean; add(n: string): unknown }

export interface VerifyInput {
  message: string;
  signature: string | Uint8Array;  // base58 string or 64 raw bytes
  address: string;
  domain: string;                  // the domain the server expects
  allowlist?: Iterable<string>;    // omit to allow any address
  now?: Date | number;
  seen: NonceStore;                // nonces already used
  clockSkewMs?: number;            // tolerance on issuedAt, default 60 s
}

export interface VerifyResult { ok: boolean; reason: Reason; fields?: MessageParams }

const HEADER = " wants you to sign in with your Solana account:";
const NONCE_RE = /^[A-Za-z0-9]{8,}$/;

export function createMessage(p: MessageParams): string {
  if (!p.domain || /[\s]/.test(p.domain)) throw new Error("domain required, no spaces");
  if (!isAddress(p.address)) throw new Error("invalid address");
  if (!NONCE_RE.test(p.nonce)) throw new Error("nonce must be 8+ alphanumeric chars");
  for (const k of ["issuedAt", "expirationTime"] as const) {
    if (Number.isNaN(Date.parse(p[k]))) throw new Error(`${k} must be ISO 8601`);
  }
  if (p.statement && /\n/.test(p.statement)) throw new Error("statement must be one line");
  const lines = [`${p.domain}${HEADER}`, p.address, ""];
  if (p.statement) lines.push(p.statement, "");
  if (p.uri) lines.push(`URI: ${p.uri}`);
  lines.push("Version: 1");
  if (p.chainId) lines.push(`Chain ID: ${p.chainId}`);
  lines.push(`Nonce: ${p.nonce}`, `Issued At: ${p.issuedAt}`, `Expiration Time: ${p.expirationTime}`);
  return lines.join("\n");
}

export function parseMessage(msg: string): MessageParams | null {
  if (typeof msg !== "string") return null;
  const lines = msg.split("\n");
  if (lines.length < 6 || !lines[0].endsWith(HEADER) || lines[2] !== "") return null;
  const domain = lines[0].slice(0, -HEADER.length);
  const address = lines[1];
  let i = 3, statement: string | undefined;
  if (lines[i] !== undefined && !/^[A-Z][A-Za-z ]+: /.test(lines[i])) {
    statement = lines[i];
    if (lines[i + 1] !== "") return null;
    i += 2;
  }
  const f: Record<string, string> = {};
  const order = ["URI", "Version", "Chain ID", "Nonce", "Issued At", "Expiration Time"];
  let last = -1;
  for (; i < lines.length; i++) {
    const m = /^([A-Za-z ]+): (.+)$/.exec(lines[i]);
    if (!m) return null;
    const idx = order.indexOf(m[1]);
    if (idx <= last || m[1] in f) return null; // unknown, duplicate or out of order
    last = idx; f[m[1]] = m[2];
  }
  if (f["Version"] !== "1" || !f["Nonce"] || !f["Issued At"] || !f["Expiration Time"]) return null;
  if (!domain || !NONCE_RE.test(f["Nonce"])) return null;
  if (Number.isNaN(Date.parse(f["Issued At"])) || Number.isNaN(Date.parse(f["Expiration Time"]))) return null;
  return {
    domain, address, statement, nonce: f["Nonce"], issuedAt: f["Issued At"], expirationTime: f["Expiration Time"],
    ...(f["URI"] ? { uri: f["URI"] } : {}), ...(f["Chain ID"] ? { chainId: f["Chain ID"] } : {}),
  };
}

function isAddress(a: string): boolean {
  try { return b58decode(a).length === 32; } catch { return false; }
}

function sigBytes(s: string | Uint8Array): Uint8Array | null {
  try {
    const b = typeof s === "string" ? b58decode(s) : s;
    return b instanceof Uint8Array && b.length === 64 ? b : null;
  } catch { return null; }
}

const SPKI_PREFIX = Buffer.from("302a300506032b6570032100", "hex");

export function verify(input: VerifyInput): VerifyResult {
  const fields = parseMessage(input.message);
  if (!fields) return { ok: false, reason: "malformed_message" };
  if (fields.domain !== input.domain) return { ok: false, reason: "wrong_domain", fields };
  if (!isAddress(input.address)) return { ok: false, reason: "invalid_address", fields };
  if (fields.address !== input.address) return { ok: false, reason: "address_mismatch", fields };
  const now = input.now === undefined ? Date.now() : +input.now;
  const skew = input.clockSkewMs ?? 60_000;
  if (Date.parse(fields.issuedAt) - skew > now) return { ok: false, reason: "not_yet_valid", fields };
  if (Date.parse(fields.expirationTime) <= now) return { ok: false, reason: "expired", fields };
  const sig = sigBytes(input.signature);
  if (!sig) return { ok: false, reason: "malformed_signature", fields };
  // Cheap checks first, but the nonce is only consumed after a valid signature,
  // so a forged request cannot burn a legitimate user's nonce.
  if (input.seen.has(fields.nonce)) return { ok: false, reason: "replayed_nonce", fields };
  if (input.allowlist !== undefined && !new Set(input.allowlist).has(fields.address)) {
    return { ok: false, reason: "not_on_allowlist", fields };
  }
  const key = createPublicKey({ key: Buffer.concat([SPKI_PREFIX, Buffer.from(b58decode(input.address))]), format: "der", type: "spki" });
  const good = edVerify(null, Buffer.from(input.message, "utf8"), key, Buffer.from(sig));
  if (!good) return { ok: false, reason: "bad_signature", fields };
  input.seen.add(fields.nonce);
  return { ok: true, reason: "ok", fields };
}
