// Types for verifyKogFee. The transaction is the jsonParsed shape returned by
// Solana getTransaction (encoding "jsonParsed", maxSupportedTransactionVersion 0).

export const TOKEN_2022_PROGRAM = "TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb";

export interface UiTokenAmount {
  amount: string; // atomic units, decimal string
  decimals: number;
}

export interface TokenBalance {
  accountIndex: number;
  mint: string;
  owner?: string;
  programId?: string;
  uiTokenAmount: UiTokenAmount;
}

export interface AccountKey {
  pubkey: string;
}

export interface ParsedInstruction {
  program?: string;
  programId?: string;
  parsed?: { type?: string; info?: Record<string, unknown> } | string;
}

export interface ParsedTransaction {
  blockTime?: number | null; // unix seconds
  slot?: number;
  meta: {
    err: unknown;
    preTokenBalances?: TokenBalance[];
    postTokenBalances?: TokenBalance[];
    innerInstructions?: { index: number; instructions: ParsedInstruction[] }[];
  } | null;
  transaction: {
    signatures: string[];
    message: { accountKeys: (AccountKey | string)[]; instructions: ParsedInstruction[] };
  };
}

export interface KogQuote {
  amount: string | bigint; // minimum fee, atomic units of the mint
  expiresAt: number; // unix seconds; the payment must land at or before this time
  payee?: string; // optional, must equal the payee argument when present
  mint?: string; // optional, must equal the mint argument when present
}

// A replay store: a Set of signatures already accepted, a plain array, or a lookup function.
export type SeenStore = Set<string> | string[] | ((signature: string) => boolean);

export interface VerifyInput {
  tx: ParsedTransaction | null | undefined;
  quote: KogQuote;
  payee: string; // payee wallet (token account owner) or the payee token account itself
  mint: string; // KOG mint address
  seen: SeenStore;
}

export type Reason =
  | "ok"
  | "no_transaction"
  | "transaction_failed"
  | "bad_quote"
  | "replay"
  | "expired_quote"
  | "no_block_time"
  | "wrong_program"
  | "wrong_mint"
  | "wrong_payee"
  | "short_fee";

export interface VerifyResult {
  ok: boolean;
  reason: Reason;
  signature?: string;
  received?: string; // atomic units credited to the payee in this mint
  required?: string;
}
