## src/verifyKogFee.ts
```ts
// Pure verifier for a KOG fee paid over x402 on Solana (SPL Token 2022).
// No RPC inside: the caller passes the parsed transaction it fetched.
//
// What counts is what the payee actually holds after the transaction, read from
// the pre and post token balances, not the amount written in an instruction.
// This makes the check hold for Token 2022 transfer fees (the withheld part is
// not counted), for several transfers in one transaction, and for a transfer that
// is taken back later in the same transaction (only the net credit counts).

import {
  TOKEN_2022_PROGRAM,
  type ParsedTransaction,
  type SeenStore,
  type TokenBalance,
  type VerifyInput,
  type VerifyResult,
} from "./types.ts";

const INT = /^[0-9]+$/;

function toAtomic(v: string | bigint): bigint | null {
  if (typeof v === "bigint") return v >= 0n ? v : null;
  if (typeof v !== "string" || !INT.test(v)) return null;
  return BigInt(v);
}

function hasSeen(seen: SeenStore, sig: string): boolean {
  if (typeof seen === "function") return seen(sig) === true;
  if (seen instanceof Set) return seen.has(sig);
  if (Array.isArray(seen)) return seen.includes(sig);
  return false;
}

function accountAt(tx: ParsedTransaction, index: number): string | undefined {
  const k = tx.transaction.message.accountKeys[index];
  return typeof k === "string" ? k : k?.pubkey;
}

interface Delta {
  account: string | undefined;
  owner: string | undefined;
  mint: string;
  programId: string | undefined;
  delta: bigint;
}

// Net change of every token account touched by the transaction.
function tokenDeltas(tx: ParsedTransaction): Delta[] {
  const pre = tx.meta?.preTokenBalances ?? [];
  const post = tx.meta?.postTokenBalances ?? [];
  const byIndex = new Map<number, { pre?: TokenBalance; post?: TokenBalance }>();
  for (const b of pre) byIndex.set(b.accountIndex, { ...byIndex.get(b.accountIndex), pre: b });
  for (const b of post) byIndex.set(b.accountIndex, { ...byIndex.get(b.accountIndex), post: b });
  const out: Delta[] = [];
  for (const [index, { pre: a, post: b }] of byIndex) {
    const ref = b ?? a!;
    const before = a ? BigInt(a.uiTokenAmount.amount) : 0n;
    const after = b ? BigInt(b.uiTokenAmount.amount) : 0n;
    out.push({
      account: accountAt(tx, index),
      owner: ref.owner,
      mint: ref.mint,
      programId: ref.programId,
      delta: after - before,
    });
  }
  return out;
}

export function verifyKogFee({ tx, quote, payee, mint, seen }: VerifyInput): VerifyResult {
  if (!tx || !tx.transaction || !Array.isArray(tx.transaction.signatures)) {
    return { ok: false, reason: "no_transaction" };
  }
  const signature = tx.transaction.signatures[0];
  if (!signature) return { ok: false, reason: "no_transaction" };
  if (!tx.meta || tx.meta.err !== null && tx.meta.err !== undefined) {
    return { ok: false, reason: "transaction_failed", signature };
  }

  const required = quote ? toAtomic(quote.amount) : null;
  if (
    required === null ||
    !Number.isFinite(quote.expiresAt) ||
    !payee ||
    !mint ||
    (quote.payee !== undefined && quote.payee !== payee) ||
    (quote.mint !== undefined && quote.mint !== mint)
  ) {
    return { ok: false, reason: "bad_quote", signature };
  }
  const base = { signature, required: required.toString() };

  if (hasSeen(seen, signature)) return { ok: false, reason: "replay", ...base };

  if (typeof tx.blockTime !== "number") return { ok: false, reason: "no_block_time", ...base };
  if (tx.blockTime > quote.expiresAt) return { ok: false, reason: "expired_quote", ...base };

  const deltas = tokenDeltas(tx);
  // The mint must be touched by the transaction at all; otherwise it paid in something else.
  if (!deltas.some((d) => d.mint === mint)) return { ok: false, reason: "wrong_mint", ...base, received: "0" };

  const toPayee = deltas.filter((d) => d.mint === mint && (d.owner === payee || d.account === payee));
  if (toPayee.some((d) => d.programId !== undefined && d.programId !== TOKEN_2022_PROGRAM)) {
    return { ok: false, reason: "wrong_program", ...base };
  }
  const received = toPayee.reduce((s, d) => s + d.delta, 0n);
  if (received <= 0n) return { ok: false, reason: "wrong_payee", ...base, received: "0" };
  if (received < required) return { ok: false, reason: "short_fee", ...base, received: received.toString() };

  return { ok: true, reason: "ok", ...base, received: received.toString() };
}
