import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { verifyKogFee } from "../src/verifyKogFee.ts";
import type { ParsedTransaction, KogQuote } from "../src/types.ts";

const BASE: ParsedTransaction = JSON.parse(
  readFileSync(new URL("../fixtures/right_fee.json", import.meta.url), "utf8"),
);
const MINT = "KoGm1nt1111111111111111111111111111111111111";
const PAYEE = "KognaiPayee111111111111111111111111111111111";
const PAYEE_ATA = "PayeeAta11111111111111111111111111111111111111";
const SIG = BASE.transaction.signatures[0];
const QUOTE: KogQuote = { amount: "1000000000", expiresAt: 1792790060 };

const tx = (edit?: (t: ParsedTransaction) => void): ParsedTransaction => {
  const t = structuredClone(BASE);
  edit?.(t);
  return t;
};
const run = (t: ParsedTransaction | null, over: Partial<{ quote: KogQuote; payee: string; mint: string; seen: any }> = {}) =>
  verifyKogFee({ tx: t, quote: QUOTE, payee: PAYEE, mint: MINT, seen: new Set<string>(), ...over });

// Acceptance items from the job spec.

test("right fee: accepted", () => {
  const r = run(tx());
  assert.deepEqual(r, { ok: true, reason: "ok", signature: SIG, required: "1000000000", received: "1000000000" });
});

test("short fee: refused", () => {
  const r = run(tx(), { quote: { ...QUOTE, amount: "1000000001" } });
  assert.equal(r.ok, false);
  assert.equal(r.reason, "short_fee");
  assert.equal(r.received, "1000000000");
});

test("wrong mint: refused", () => {
  const r = run(tx(), { mint: "OtherM1nt111111111111111111111111111111111111" });
  assert.equal(r.ok, false);
  assert.equal(r.reason, "wrong_mint");
});

test("wrong payee: refused", () => {
  const r = run(tx(), { payee: "SomeoneE1se11111111111111111111111111111111" });
  assert.equal(r.ok, false);
  assert.equal(r.reason, "wrong_payee");
});

test("expired quote: refused, and the boundary second is still valid", () => {
  assert.equal(run(tx(), { quote: { ...QUOTE, expiresAt: BASE.blockTime! - 1 } }).reason, "expired_quote");
  assert.equal(run(tx(), { quote: { ...QUOTE, expiresAt: BASE.blockTime! } }).ok, true);
});

test("replay: refused for a Set, an array and a lookup function", () => {
  assert.equal(run(tx(), { seen: new Set([SIG]) }).reason, "replay");
  assert.equal(run(tx(), { seen: [SIG] }).reason, "replay");
  assert.equal(run(tx(), { seen: (s: string) => s === SIG }).reason, "replay");
  assert.equal(run(tx(), { seen: ["another"] }).ok, true);
});

// Cases a real payment gate meets.

test("failed transaction: refused even if balances look right", () => {
  const r = run(tx((t) => { t.meta!.err = { InstructionError: [0, { Custom: 1 }] }; }));
  assert.equal(r.reason, "transaction_failed");
});

test("missing transaction or meta: refused", () => {
  assert.equal(run(null).reason, "no_transaction");
  assert.equal(run(tx((t) => { t.meta = null; })).reason, "transaction_failed");
});

test("payee given as its token account: accepted", () => {
  assert.equal(run(tx(), { payee: PAYEE_ATA }).ok, true);
});

test("Token 2022 transfer fee: only the net credit counts", () => {
  // 1.0 KOG sent, 1 percent withheld by the transfer fee extension: payee balance rises by 0.99.
  const t = tx((t) => { t.meta!.postTokenBalances![1].uiTokenAmount.amount = "990000000"; });
  assert.equal(run(t).reason, "short_fee");
  assert.equal(run(t, { quote: { ...QUOTE, amount: "990000000" } }).ok, true);
